-- certifications_data_analytics.sql
-- Why: the data_intel positions (intel_director, analytics, bi_analyst, knowledge_director,
-- market_analyst, supplier_analyst) are only credible if they can sit the real exams their
-- certifications come from. This file authors the SIX question banks owned by this batch:
--   CAP (Certified Analytics Professional)            - INFORMS, seven domains
--   CDMP (Certified Data Management Professional)     - DAMA-DMBOK knowledge areas
--   Google Professional Data Engineer                 - Google exam guide sections
--   Microsoft PL-300 Power BI Data Analyst            - PL-300 skills measured
--   CKM (Certified Knowledge Manager)                 - KM Institute KM framework
--   MRS Advanced Certificate in Market and Social Research Practice - MRS syllabus
-- 40 questions each, real-exam difficulty (scenario/application), 4 options, one key,
-- a two-sentence rationale, exactly 10 keys per letter and 10 'hard' per bank (25%).
-- The marketplace this company runs is well represented: cohort and funnel analysis,
-- experiment design and significance, sampling bias, data quality and lineage, retrieval
-- and knowledge governance, and reading a survey honestly.
-- role_certification rows and the sitter belong to a sibling author; this file does NOT touch them.
-- Every bank is guarded so the FIRST author of a shared certification wins.
--
-- Apply: node scripts/apply_sql.mjs scripts/sql/certifications_data_analytics.sql --apply --ddl

-- ============================== CAP (Certified Analytics Professional) (INFORMS, seven domains) ==============================
insert into public.certification_exam_question
  (certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
select * from (values
('CAP (Certified Analytics Professional)','Business Problem Framing','exam','A marketplace sponsor asks for "a model that fixes our supplier response problem". What is the analytics professional''s first obligation?','Choose an algorithm family that fits the available data','Estimate the compute budget for training','Restate the request as a measurable business problem with a decision it will change','Build a baseline model to show early progress','C','Business problem framing requires converting a vague sponsor request into a specific problem statement tied to a decision and a measurable outcome. Selecting methods or building baselines before the problem is framed risks solving the wrong problem.'),
('CAP (Certified Analytics Professional)','Business Problem Framing','hard','Two stakeholders define "supplier active" differently: one means quoted in 30 days, the other means registered. What should be documented before analysis proceeds?','A confusion matrix for the two definitions','An agreed operational definition with its owner and effective date','A statistical test of which definition is more common','A data dictionary generated automatically from the schema','B','Conflicting operational definitions are a framing defect, not a modelling one, and must be resolved and owned before any measurement is trusted. Automated dictionaries record columns, not the business meaning stakeholders disagreed on.'),
('CAP (Certified Analytics Professional)','Business Problem Framing','exam','A sponsor will only act if the answer arrives before the weekly buying meeting. How should this affect the engagement?','It is a deployment detail to be handled after modelling','It only matters if the model is retrained frequently','It is irrelevant to problem framing','It becomes a stated constraint that bounds acceptable methods and data latency','D','A decision deadline is a business constraint that limits which methods and refresh cadences are feasible, so it belongs in framing. Deferring it often produces an accurate model that arrives too late to change the decision.'),
('CAP (Certified Analytics Professional)','Business Problem Framing','hard','An executive asks for the "ROI of the analytics project" before any model exists. The most defensible response is to','Refuse until the model is deployed and measured','Express value as the decision volume times the expected improvement per decision, with stated assumptions','Quote an industry benchmark ROI for analytics projects','Use the project cost as a proxy for its value','B','Expected value at framing time is estimated from decision volume and plausible per-decision improvement, with assumptions made explicit and testable. Benchmarks and cost figures say nothing about this organisation''s decisions.'),
('CAP (Certified Analytics Professional)','Analytics Problem Framing','exam','A team wants to reduce buyers abandoning the RFQ form. Which analytics problem statement is best specified?','Predict, for each started RFQ, the probability it is abandoned before submission, to target an intervention','Understand why buyers abandon RFQs','Improve the RFQ experience using machine learning','Cluster buyers into segments','A','A well specified analytics problem names the unit of analysis, the target, and the use of the output. The other options omit the target or the decision the output will drive.'),
('CAP (Certified Analytics Professional)','Analytics Problem Framing','exam','Which pairing of business objective and analytics metric is coherent?','Increase supplier coverage; optimise model AUC only','Reduce quote turnaround; maximise regression R-squared on price','Reduce non-response; maximise recall of suppliers who will not respond at a fixed contact budget','Increase revenue; minimise mean absolute error of registration counts','C','The analytics metric must reflect the operational constraint, here a fixed number of contacts, which makes recall at a budget the coherent choice. The other pairs optimise a statistic disconnected from the action taken.'),
('CAP (Certified Analytics Professional)','Analytics Problem Framing','exam','Reframing a churn question from "who will churn" to "who will churn AND can be saved by our offer" changes the problem to one of','Better feature engineering','Uplift, that is, estimating the incremental effect of the treatment','Higher model capacity','Longer training windows','B','Targeting those whose behaviour the intervention changes is an uplift or incremental-response problem, not a plain propensity problem. Ranking by churn risk alone wastes offers on those who would have stayed anyway.'),
('CAP (Certified Analytics Professional)','Analytics Problem Framing','hard','A fraud screen must flag at most 40 cases per day for human review. The correct framing metric is','Overall accuracy','Area under the ROC curve','F1 score at the default 0.5 threshold','Precision at k, with k equal to the daily review capacity','D','When the action budget is fixed, only the top k ranked cases are acted on, so precision at k measures what the reviewers actually experience. Threshold-free or default-threshold measures ignore the capacity constraint that defines the workflow.'),
('CAP (Certified Analytics Professional)','Data','exam','A supplier table has a row per contact event and an analyst averages "days to respond" across all rows. Highly active suppliers dominate the average. This is','A unit-of-analysis error inflating the weight of frequent responders','A sampling error caused by too few rows','A model overfitting problem','A rounding error','A','Averaging at the event level weights each supplier by activity rather than treating each supplier equally, which is a unit-of-analysis defect. The fix is to aggregate to supplier level first, or to weight explicitly and say so.'),
('CAP (Certified Analytics Professional)','Data','exam','Registration timestamps are stored in UTC but funnel reports use Dubai local time. What is the practical consequence if this is ignored?','No consequence, since duration differences cancel','Day boundaries shift by four hours, mis-assigning events near midnight and distorting daily cohorts','All durations become negative','Only leap years are affected','B','A four-hour offset moves events across day boundaries, which changes which cohort or reporting day each event lands in. Durations are unaffected but daily counts and cohort membership are.'),
('CAP (Certified Analytics Professional)','Data','exam','Which check best detects that an upstream extract silently truncated yesterday''s load?','A schema check that all expected columns exist','A row-count and key-coverage comparison against the expected distribution for that day','A null check on the primary key','A spell check on category labels','A','Missing columns are the one failure a schema check reliably catches, but truncation shows as volume loss; the strongest single detector of truncation is comparing counts and key coverage against expectation.'),
('CAP (Certified Analytics Professional)','Data','hard','Lineage for a revenue figure shows it is derived from a view that was redefined last month without versioning. The correct professional response is','Re-run the numbers and publish; the current definition is authoritative','Ignore lineage because the totals still reconcile to the ledger','Restate the affected historical series or clearly annotate the definitional break, and add versioning to the view','Delete the historical series to avoid confusion','C','An unversioned definitional change makes a time series non-comparable across the break, so it must be restated or annotated rather than presented as continuous. Deleting history destroys evidence and reconciling totals does not repair comparability.'),
('CAP (Certified Analytics Professional)','Methodology Selection','exam','A stakeholder must explain to a regulator why any individual supplier was rejected. Which method choice is most appropriate?','A monotonic, interpretable model such as regularised logistic regression or a scorecard','A deep neural network with post-hoc saliency maps','A large ensemble with feature importances only','A nearest-neighbour model over embeddings','A','Regulatory explanation of individual decisions favours models whose reasons are inherent and reproducible per case. Global feature importances and post-hoc attributions do not constitute a per-decision explanation.'),
('CAP (Certified Analytics Professional)','Methodology Selection','exam','With 300 labelled outcomes and 80 candidate features, the largest methodological risk is','Insufficient compute','Slow inference at serving time','Data drift in the first week','Overfitting, so the plan needs strong regularisation, feature reduction and nested cross-validation','D','With features approaching the sample size, variance dominates and in-sample performance becomes badly optimistic. Regularisation, dimension reduction and nested resampling are the standard controls.'),
('CAP (Certified Analytics Professional)','Methodology Selection','exam','Time-ordered marketplace data is validated with random k-fold cross-validation. The likely effect is','A pessimistic estimate because folds are smaller','No effect if the data are stationary','An optimistic estimate because future information leaks into training folds','An unbiased estimate provided the folds are stratified','C','Random folds let later observations inform earlier predictions, which cannot happen in production and inflates the estimate. Time-series or forward-chaining splits preserve the ordering the deployed model faces.'),
('CAP (Certified Analytics Professional)','Methodology Selection','hard','Two methods score identically on validation, but one requires a nightly feature that arrives two hours after the decision point. The professional should','Prefer the method whose features are available at decision time, even at equal or slightly lower accuracy','Prefer the more accurate method and accept a two-hour stale decision','Average the two models','Retrain the late-feature model more often','A','A feature unavailable at the moment of decision cannot be used in production, and building on it creates a training-serving skew that silently degrades live performance. Availability at decision time is a hard feasibility constraint, not a tie-breaker.'),
('CAP (Certified Analytics Professional)','Model Building','exam','A classifier is trained on rows where the outcome is only observed for suppliers who were contacted. Without correction, the model estimates','The probability of response conditional on having been contacted, not the population probability','The unconditional population probability','The causal effect of contact','Nothing measurable','A','Outcomes observed only under the historical contact policy give a conditional quantity shaped by that policy, a selection effect. Treating it as the population rate transfers the old policy''s biases into the new one.'),
('CAP (Certified Analytics Professional)','Model Building','exam','Class balance is 2 percent positive. Which practice is most defensible?','Delete negatives at random until classes are balanced and report raw probabilities','Keep the natural prevalence or resample, but calibrate probabilities back to the true base rate','Report accuracy as the headline metric','Raise the decision threshold to 0.9','B','Resampling changes the implied prior, so probabilities must be recalibrated to the true prevalence before they are used for expected-value decisions. Accuracy is uninformative at 2 percent prevalence.'),
('CAP (Certified Analytics Professional)','Model Building','exam','A feature "number of previous quotes accepted" is computed using the full history, including quotes after the prediction date. This is','Acceptable if the field is stable','Acceptable because it improves accuracy','Target leakage that invalidates the validation estimate','A missing-data problem','C','Any feature built from information unavailable at prediction time leaks the future into training and produces validation scores that cannot be reproduced live. Features must be constructed as-of the prediction timestamp.'),
('CAP (Certified Analytics Professional)','Model Building','hard','A model''s probabilities are used to compute expected margin per RFQ. Which diagnostic matters most?','Discrimination measured by AUC','Training loss','Feature importance stability','Calibration, checked by a reliability curve or calibration error','D','Expected-value arithmetic multiplies the predicted probability by a monetary amount, so the probabilities must mean what they say. A model can rank perfectly, with excellent AUC, and still be badly miscalibrated.'),
('CAP (Certified Analytics Professional)','Deployment','exam','The safest first production step for a scoring model that changes who gets contacted is','A shadow or champion-challenger deployment scoring live traffic without acting, compared against the incumbent','A full cutover with a rollback plan','Deployment to the largest segment only','Deployment during the quietest week','A','Shadow scoring exposes the model to real live inputs and reveals pipeline and skew defects without exposing customers to its decisions. Full cutovers discover those defects through customer impact.'),
('CAP (Certified Analytics Professional)','Deployment','exam','Training used a batch feature store while serving computes features in application code. The central risk is','Higher latency only','Training-serving skew, where the same input yields different features in the two paths','Increased storage cost','Loss of interpretability','B','Two independent implementations of the same feature drift apart, so the model sees inputs at serving that differ from those it learned on. Sharing one transformation, or reconciling the two continuously, is the control.'),
('CAP (Certified Analytics Professional)','Deployment','exam','An A/B test of a new ranking model reaches significance on day two of a planned fourteen-day run. The analyst should','Stop and ship, since significance was reached','Stop and declare no effect','Continue to the planned horizon, because stopping at the first significant look inflates the false positive rate','Extend the test indefinitely','C','Repeatedly testing and stopping at the first significant result greatly inflates type I error unless a sequential design with spending was pre-specified. Running to the pre-registered horizon preserves the stated error rate.'),
('CAP (Certified Analytics Professional)','Deployment','hard','A pilot shows a 3 percent lift, but the treatment group also received a concurrent email campaign. The correct conclusion is','The lift is 3 percent from the model','The lift is at most 3 percent','The lift is at least 3 percent','The effects are confounded and the model''s isolated effect is not identified from this design','D','When two treatments move together, no contrast in the data separates their effects, so the model''s own effect is not identified. A factorial or holdout design would be needed to attribute it.'),
('CAP (Certified Analytics Professional)','Model Lifecycle Management','exam','Input distributions shift but observed accuracy is unchanged. The right action is','Retrain immediately','Ignore it, since accuracy is the only thing that matters','Delete the drifted features','Log the drift, keep monitoring, and investigate whether the label delay is masking degradation','D','Covariate drift without a measured performance change may simply be harmless, or the labels may not have arrived yet to reveal harm. Recording the drift and checking label latency separates the two before acting.'),
('CAP (Certified Analytics Professional)','Model Lifecycle Management','exam','A model retrains nightly on its own accepted recommendations only. Over months this produces','A feedback loop that narrows exploration and confirms the model''s own prior beliefs','Better calibration through repetition','Unbiased estimates by the law of large numbers','No effect if the data volume grows','A','Training only on outcomes from cases the model chose starves it of counterfactual evidence and entrenches its current view. Deliberate exploration or a randomised holdout keeps the feedback loop honest.'),
('CAP (Certified Analytics Professional)','Model Lifecycle Management','exam','What is the minimum needed to reproduce a decision the model made six months ago?','The current model artefact','The source code repository','Versioned model artefact, feature definitions, input snapshot and the code and configuration in force at that time','The prediction log alone','C','Reproduction requires every input to the computation as it stood then, since any one of them drifting changes the output. A prediction log records what happened but not why it happened.'),
('CAP (Certified Analytics Professional)','Model Lifecycle Management','hard','A retired model is replaced. Which lifecycle obligation is most often missed and most costly?','Archiving the training notebooks','Decommissioning the upstream feature pipelines and alerts the retired model owned, so silent stale data does not feed successors','Publishing a press release','Deleting the model artefact','B','Retirement leaves orphaned pipelines and monitors that stop being maintained yet keep feeding downstream consumers, which is how silent stale data spreads. Decommissioning them is part of retiring the model, not an optional extra.'),
('CAP (Certified Analytics Professional)','Data','exam','Weekly cohorts of registered suppliers show a rising 30-day activation rate, but the most recent two cohorts look best of all. The most likely explanation is','A genuine step change in onboarding','The recent cohorts have not had 30 full days, so their windows are incomplete','Seasonality in supplier demand','A change in the definition of activation','B','A 30-day metric for a cohort younger than 30 days is censored and must not be plotted alongside complete cohorts. Excluding or clearly shading immature cohorts prevents the illusion of improvement.'),
('CAP (Certified Analytics Professional)','Analytics Problem Framing','exam','A funnel shows RFQ to quote conversion of 60 percent overall, but 30 percent in every individual category. This pattern indicates','A calculation error, since the overall rate cannot exceed all parts','Simpson''s paradox driven by differing category volumes and mix','That categories should be ignored','Random noise','C','Aggregate rates are volume-weighted mixtures, so a shifting mix can move the total in a direction no subgroup moved. Reporting the mix alongside the total is the honest presentation.'),
('CAP (Certified Analytics Professional)','Methodology Selection','exam','The business wants to know whether a price change caused more quotes, and randomisation is impossible. Which design is strongest among these?','Before-and-after comparison in the treated market','Correlation of price with quotes across all history','A cross-sectional regression with many controls','Difference-in-differences against comparable untreated markets, with a parallel-trends check','D','Difference-in-differences removes shared time shocks by using an untreated comparison group, provided pre-treatment trends are parallel. Simple before-and-after comparisons attribute every concurrent change to the price move.'),
('CAP (Certified Analytics Professional)','Model Building','exam','With 900 observations, adding a 400-level categorical feature by one-hot encoding most likely','Adds high-cardinality sparsity and overfitting risk; target or frequency encoding with regularisation is safer','Reduces variance','Guarantees better generalisation','Has no effect on the model','A','Four hundred dummies over 900 rows leaves almost no data per level, so the model memorises levels rather than learning signal. Regularised target or frequency encodings pool information across levels.'),
('CAP (Certified Analytics Professional)','Business Problem Framing','exam','Which statement best distinguishes a KPI from a diagnostic metric?','A KPI is always a ratio','A KPI expresses the outcome the organisation is accountable for; a diagnostic metric explains movement in it','A diagnostic metric is measured less often','They are interchangeable','B','KPIs carry accountability for an outcome, while diagnostics decompose that outcome to explain why it moved. Confusing them leads teams to manage the explanation instead of the result.'),
('CAP (Certified Analytics Professional)','Deployment','exam','Business users will consume scores through an existing operational screen. The most important deployment consideration is','The training framework used','That the score arrives with the context and threshold guidance the user needs to act, within their workflow latency','The number of model parameters','The colour scheme of the chart','B','A score only creates value when it reaches the decision maker in time and with enough context to change the action. Model internals are irrelevant at the point of consumption.'),
('CAP (Certified Analytics Professional)','Model Lifecycle Management','hard','Which monitoring signal would most reliably catch a broken upstream join that silently nulls a key feature?','A drop in downstream revenue','A rise in model latency','A weekly stakeholder review','A feature-level null-rate and distribution monitor with alerting thresholds','D','Null-rate monitoring detects the defect at the feature where it occurs, within one scoring cycle, before it propagates. Revenue and review cadences detect it far downstream and much later.'),
('CAP (Certified Analytics Professional)','Data','exam','Two systems disagree on the count of active suppliers. The first analytical step is','Average the two counts','Take the larger number as the safer estimate','Reconcile the definitions, filters and as-of timestamps of each count before comparing values','Rebuild both systems','C','Most count disputes are definitional or temporal rather than arithmetic, so the definitions and as-of times must be aligned first. Averaging or picking one hides the real disagreement.'),
('CAP (Certified Analytics Professional)','Methodology Selection','exam','A survey of 400 suppliers reports 62 percent satisfaction with a margin of error of roughly plus or minus 5 points. A follow-up of 400 reports 65 percent. The correct statement is','The difference is within sampling error and is not evidence of a real change','Satisfaction rose by 3 points','Satisfaction rose significantly','The sample was too small to say anything at all','A','Two intervals of about plus or minus 5 points around 62 and 65 overlap heavily, so the data are consistent with no change. A sample of 400 is informative; it simply cannot resolve a 3-point difference.'),
('CAP (Certified Analytics Professional)','Analytics Problem Framing','exam','Which requirement most clearly makes a request a causal question rather than a predictive one?','The sponsor asks who is most likely to convert next month','The sponsor asks for a dashboard refresh','The sponsor asks what would happen if we changed the fee','The sponsor asks for a segmentation','C','A question about the effect of an intervention is counterfactual and needs a design that identifies causation. Predicting who converts under current policy requires no such design.'),
('CAP (Certified Analytics Professional)','Model Building','exam','Missing values in a supplier credit field are not missing at random: absent values indicate the supplier never completed onboarding. The best handling is','Drop the column','Drop those rows','Impute the mean and proceed','Encode missingness explicitly as an informative category or indicator alongside imputation','D','When missingness itself carries signal, discarding or silently imputing it destroys information and biases the estimate. An explicit indicator lets the model use the fact of absence.'),
('CAP (Certified Analytics Professional)','Business Problem Framing','hard','A sponsor insists on a single number to describe supplier quality across ten dimensions. The professional''s best contribution is','Refuse to produce any composite','Produce the composite silently using equal weights','Average the ten ranks without comment','Build the composite with explicit, agreed weights, publish a sensitivity analysis, and report the dimensions that drive it','D','Composites are legitimate when their weights are explicit and their sensitivity to those weights is shown, because the weights are value judgements the sponsor owns. Silent equal weighting conceals a decision that materially changes the ranking.')
) as v(certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
where not exists (select 1 from public.certification_exam_question where certification = 'CAP (Certified Analytics Professional)');

-- ============================== CDMP (Certified Data Management Professional) (DAMA-DMBOK knowledge areas) ==============================
insert into public.certification_exam_question
  (certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
select * from (values
('CDMP (Certified Data Management Professional)','Data Governance','exam','A business unit wants to change the definition of "active supplier". Under DAMA-DMBOK governance, who decides?','The data engineer who owns the pipeline','The most senior requester','The accountable data steward or governance body for that data domain, through the change process','Whoever consumes the metric most','C','DMBOK places accountability for the meaning of data with the stewardship structure for the domain, exercised through a defined change process. Pipeline ownership and seniority are neither accountability nor process.'),
('CDMP (Certified Data Management Professional)','Data Governance','exam','Which statement best distinguishes data governance from data management?','Governance decides what must be done and who is accountable; management executes it','Governance is technical and management is commercial','They are synonyms in DMBOK','Governance applies only to personal data','A','DMBOK frames governance as the exercise of authority and decision rights over data assets, while the other knowledge areas carry out the work. Conflating them leaves decisions unowned.'),
('CDMP (Certified Data Management Professional)','Data Governance','exam','A governance programme publishes policies that nobody follows. The most effective next step is','Publish the policies again with stronger wording','Embed the policy as an enforced control in the workflow that creates the data, with a measured compliance metric','Move governance under the IT department','Reduce the number of policies to one','B','Policy that is not embodied in the operational process and measured has no mechanism to change behaviour. Controls at the point of data creation are where compliance becomes observable.'),
('CDMP (Certified Data Management Professional)','Data Quality','hard','Which pair of data quality dimensions is being tested by "every RFQ has a buyer that exists in the buyer master, and no RFQ is duplicated"?','Timeliness and accuracy','Validity and precision','Consistency and volatility','Referential integrity, a facet of consistency, and uniqueness','D','A foreign-key style rule tests consistency across data sets, and the no-duplicate rule tests uniqueness. Neither statement says anything about how current or how correct the values are.'),
('CDMP (Certified Data Management Professional)','Data Quality','exam','A data quality rule fires 4,000 exceptions on its first run. The best response is','Profile and triage by business impact, fix the highest-impact root causes, and phase in the rule','Suppress the rule until the data improves','Auto-correct all 4,000 records','Escalate every exception to the executive sponsor','A','Mass exception output on first run reflects historical debt and must be triaged by impact rather than treated as an incident queue. Root-cause fixes upstream stop new exceptions from being created.'),
('CDMP (Certified Data Management Professional)','Data Quality','exam','Which measure best expresses completeness for a supplier profile?','The number of suppliers in the table','The proportion of records populated for fields that are required by the business rule','The average length of the free-text description','The number of columns in the table','B','Completeness is measured against what the business requires to be present, not against every possible field. Counting rows or columns measures volume and structure, not completeness.'),
('CDMP (Certified Data Management Professional)','Data Quality','exam','A quality dashboard reports 99.8 percent accuracy while users report constant errors. The most likely cause is','Users are mistaken','The rules measure format and presence rather than the semantic correctness users experience','The dashboard refresh is too fast','Accuracy above 99 percent is always sufficient','B','Automated rules typically test syntax, presence and range, which is a weak proxy for whether a value is true of the real-world object. Reconciling to an authoritative source is what tests accuracy.'),
('CDMP (Certified Data Management Professional)','Data Modeling and Design','hard','A supplier may hold many certifications and a certification may be held by many suppliers, and the date it was granted must be stored. The correct logical design is','A repeating group of certification columns on the supplier entity','A comma-separated certification list on the supplier entity','An associative entity between supplier and certification carrying the granted date','A certification entity with a supplier_id foreign key','C','A many-to-many relationship with its own attribute resolves to an associative entity that carries that attribute. Repeating groups and delimited lists violate first normal form, and a single foreign key would force one supplier per certification.'),
('CDMP (Certified Data Management Professional)','Data Modeling and Design','exam','Third normal form is violated when','A table has a composite primary key','A non-key attribute depends on another non-key attribute','A table has more than ten columns','A foreign key is nullable','B','Transitive dependence of a non-key attribute on another non-key attribute is precisely the 3NF violation. Key composition, column count and nullability are unrelated to the normal form.'),
('CDMP (Certified Data Management Professional)','Data Modeling and Design','exam','Which is the correct order of model abstraction in DMBOK?','Physical, logical, conceptual','Logical, conceptual, physical','Conceptual, physical, logical','Conceptual, logical, physical','D','DMBOK progresses from a technology-independent conceptual view, through a normalised logical model, to a physical model bound to a platform. The other orders invert or scramble that progression.'),
('CDMP (Certified Data Management Professional)','Metadata Management','exam','A regulator asks which reports would be wrong if a source column were dropped. Which metadata answers this directly?','Business glossary definitions','Technical lineage linking source columns to downstream transformations and reports','Data quality scores','Access control lists','B','Impact analysis is exactly the forward-lineage question, which requires column-level dependency metadata. Glossaries define meaning and quality scores describe condition, neither traces dependence.'),
('CDMP (Certified Data Management Professional)','Metadata Management','exam','What distinguishes a business glossary from a data dictionary?','The glossary defines business terms and their meaning; the dictionary describes physical data structures','The glossary is machine-generated and the dictionary is manual','They are the same artefact under two names','The glossary applies only to reports','A','A glossary is the agreed vocabulary of the business, independent of any system, while the dictionary records tables, columns and types. Keeping them linked is what lets a term be traced to its physical implementation.'),
('CDMP (Certified Data Management Professional)','Metadata Management','hard','A metadata catalogue is populated once by a scan and then never refreshed. The main governance failure is','The catalogue consumed too much storage','Metadata now silently misrepresents the estate, so decisions based on it are unreliable and trust in the catalogue collapses','Nothing, since schemas rarely change','The scan should have used a different tool','B','Stale metadata is worse than no metadata because it is consulted with confidence while being wrong. Sustained harvesting and freshness monitoring are part of the metadata management capability.'),
('CDMP (Certified Data Management Professional)','Data Integration and Interoperability','exam','Which pattern best suits near-real-time propagation of supplier status to several consumers?','Nightly full-table extract to each consumer','Publish-subscribe event streaming with change data capture at the source','Manual CSV exchange','A weekly reconciliation report','B','Change data capture with a publish-subscribe channel delivers each change once to many consumers with low latency. Batch extracts and manual exchange cannot meet a near-real-time requirement.'),
('CDMP (Certified Data Management Professional)','Data Integration and Interoperability','exam','In ELT rather than ETL, the transformation','Occurs in the target platform after loading raw data','Occurs before extraction','Is eliminated entirely','Occurs only in the source system','A','ELT loads raw data first and transforms inside the target, exploiting the target platform''s compute and preserving the raw layer. The transformation is relocated, not removed.'),
('CDMP (Certified Data Management Professional)','Data Integration and Interoperability','exam','An integration re-sends a message after a timeout, creating duplicate suppliers. The correct control is','Increase the timeout','Idempotent processing keyed on a stable business or message identifier','Disable retries entirely','Deduplicate manually each morning','B','Idempotency makes a repeated delivery harmless, which is the only robust answer under at-least-once delivery. Longer timeouts and disabled retries trade one failure mode for another.'),
('CDMP (Certified Data Management Professional)','Master and Reference Data Management','hard','"Emirates Steel LLC", "Emirates Steel L.L.C." and "emirates steel" appear as three suppliers. The MDM capability that resolves this is','Reference data management','Data archiving','Entity resolution and survivorship rules producing a golden record','Schema evolution','C','Matching variant records to one real-world entity and choosing surviving attribute values is entity resolution with survivorship, the core of master data management. Reference data governs code lists, not entity identity.'),
('CDMP (Certified Data Management Professional)','Master and Reference Data Management','exam','Which of these is reference data rather than master data?','The supplier record for a specific company','The list of ISO country codes','A buyer''s contact details','An individual RFQ','B','Reference data is a controlled set of permissible values shared across systems, such as country or currency codes. Specific suppliers, buyers and transactions are master or transactional data.'),
('CDMP (Certified Data Management Professional)','Master and Reference Data Management','exam','In a registry-style MDM architecture, the golden record is','Physically consolidated in the hub, replacing source records','Assembled on demand from source systems using cross-reference keys held in the hub','Stored only in the data warehouse','Not permitted','B','A registry hub stores identity cross-references and composes the golden view at read time, leaving sources authoritative. Physical consolidation describes a transaction or centralised hub style instead.'),
('CDMP (Certified Data Management Professional)','Data Warehousing and Business Intelligence','exam','A supplier changes address and history must remain accurate for past quotes. The dimension technique required is','Type 1 overwrite','Type 0 fixed attribute','Type 2, adding a new row with effective dates and a current flag','Deleting and reloading the dimension','C','Type 2 slowly changing dimensions preserve the attribute values in force at each point in time, which is what historical accuracy requires. Overwriting silently restates history.'),
('CDMP (Certified Data Management Professional)','Data Warehousing and Business Intelligence','exam','A fact table stores one row per quote line with quantity and amount, and a snapshot of the running total. The running total column is','A non-additive or semi-additive fact that must not be summed across quote lines','A fully additive fact','A degenerate dimension','A junk dimension','A','Balances and running totals cannot be summed across the grain without double counting, which makes them semi-additive at best. Marking additivity in the model prevents incorrect aggregation.'),
('CDMP (Certified Data Management Professional)','Data Warehousing and Business Intelligence','hard','Two marts report different revenue because each defines the grain differently. The DMBOK remedy is','Let each mart keep its own definition and footnote the difference','Merge the two marts into one table','Establish conformed dimensions and agreed facts across marts, with the grain documented and enforced','Report only the higher figure','C','Conformed dimensions and explicitly declared grain are the mechanism that makes marts comparable in a bus architecture. Footnoting a permanent inconsistency institutionalises the defect.'),
('CDMP (Certified Data Management Professional)','Data Security','exam','Analysts need to study supplier behaviour but must not see identities. The most appropriate control is','Encrypt the database at rest','Grant read access and rely on an acceptable-use policy','Delete the data after analysis','Pseudonymise or tokenise identifiers in the analytical copy, with re-identification keys held separately under access control','D','Removing direct identifiers from the analytical copy while restricting the key gives analysts utility without exposing identity. Encryption at rest does not restrict an authorised reader, and policy alone is not a control.'),
('CDMP (Certified Data Management Professional)','Data Security','exam','Under the UAE Personal Data Protection Law, processing personal data generally requires','A lawful basis such as consent or one of the specified exemptions, with purpose limitation observed','A written contract with every data subject','Storage exclusively outside the UAE','No basis, provided the data is commercial','A','The PDPL is a consent-and-lawful-basis regime with purpose limitation and data subject rights, in line with international norms. Neither a contract with each subject nor offshore storage is a lawful basis.'),
('CDMP (Certified Data Management Professional)','Data Security','exam','Which control best limits the blast radius of a compromised analyst account?','Least-privilege, role-based access with time-bound elevation for sensitive data','A longer password policy','Quarterly access reviews only','Full-disk encryption on laptops','A','Least privilege bounds what any single compromised identity can reach, which is precisely blast radius. Password length and periodic reviews reduce likelihood or detect drift but do not bound the damage.'),
('CDMP (Certified Data Management Professional)','Data Architecture','hard','A data mesh is proposed for a company of nine people with one platform team. The strongest professional objection is','Data mesh cannot work with cloud platforms','Data mesh forbids central governance','Domain-oriented ownership assumes multiple autonomous domain teams; at this scale it adds federation overhead without the scaling problem it solves','Data mesh requires more than ten data sources','C','Mesh exists to relieve a central bottleneck across many autonomous domains, a condition a single small team does not have. Adopting its federation machinery without that condition adds cost and no benefit.'),
('CDMP (Certified Data Management Professional)','Data Architecture','exam','What does an enterprise data architecture primarily deliver?','A list of approved database vendors','The physical tuning parameters of each system','A blueprint of subject areas, data flows and standards that guides system design toward the target state','The backup schedule','C','Data architecture describes the structure and movement of data across the enterprise and sets standards that individual designs conform to. Vendor lists, tuning and backups are operational details beneath it.'),
('CDMP (Certified Data Management Professional)','Data Governance','exam','A steward, an owner and a custodian are involved in one data set. The custodian is','Accountable for the business meaning','Accountable for the value the data creates','Responsible for the technical care and operation of the data in the systems that hold it','The consumer of the data','C','DMBOK assigns technical safekeeping, operation and control implementation to the custodian, while stewardship carries meaning and quality accountability. Ownership carries the accountability for the asset itself.'),
('CDMP (Certified Data Management Professional)','Document and Content Management','hard','A retention schedule says supplier contracts are kept seven years after expiry. A contract expired in 2019 is still in the active store in 2026. The failure is','A backup failure','A search indexing failure','An access control failure','Records retention and disposition are not being executed against the schedule','D','Retention schedules require active disposition, not merely a stated period, and unexecuted schedules create legal and storage exposure. The record is present and reachable, so backup, search and access are all working.'),
('CDMP (Certified Data Management Professional)','Document and Content Management','exam','Unstructured contract PDFs must become searchable by counterparty and value. The enabling capability is','Content extraction and enrichment producing indexed metadata for each document','Increasing storage capacity','Compressing the files','Renaming the files by date','A','Making unstructured content findable requires extracting entities and attributes into structured, indexed metadata. Storage, compression and naming do not create searchable attributes.'),
('CDMP (Certified Data Management Professional)','Data Quality','exam','Which is the strongest root-cause control for repeated bad postal codes at entry?','A weekly cleansing job','A monthly quality report','Validation and reference-list selection at the point of capture','Training material for the sales team','C','Preventing invalid values at capture stops the defect being created, which is where root-cause control belongs. Downstream cleansing and reporting repeatedly treat the symptom.'),
('CDMP (Certified Data Management Professional)','Metadata Management','exam','Which metadata type records that a table is refreshed hourly and last succeeded at 06:00?','Business metadata','Semantic metadata','Structural metadata','Operational metadata','D','Operational metadata describes the running of data processes, including schedules, run outcomes and freshness. Business and structural metadata describe meaning and shape, not execution.'),
('CDMP (Certified Data Management Professional)','Data Integration and Interoperability','exam','A consumer must reprocess the last thirty days after a bug. The design property that makes this possible is','An immutable, replayable raw landing zone retained for at least that window','Higher warehouse compute','A larger message queue buffer only','More frequent snapshots of the final table','A','Replay requires the original inputs to still exist unchanged for the required window. Downstream compute and final-table snapshots cannot reconstruct inputs that were never retained.'),
('CDMP (Certified Data Management Professional)','Data Warehousing and Business Intelligence','exam','A self-service BI environment shows twelve competing "revenue" measures. The governance response is','Delete all but one report','Ask each author to document their measure','Ban self-service reporting','Certify a single governed measure in a shared semantic layer and mark uncertified measures as such','D','A certified measure in a shared semantic layer gives self-service users the governed definition by default while keeping their autonomy. Banning self-service or relying on individual documentation does not converge the definitions.'),
('CDMP (Certified Data Management Professional)','Master and Reference Data Management','hard','Which match strategy best balances false merges against missed merges for company names?','Exact string match only','Merge anything above 50 percent similarity automatically','Manual review of every pair','Deterministic matching on strong identifiers, probabilistic matching on weaker attributes, with a human review band for borderline scores','D','Layering deterministic rules on strong identifiers with a scored probabilistic tier and a stewardship review band controls both error types explicitly. Exact-only misses variants, and a low automatic threshold creates false merges that are expensive to unwind.'),
('CDMP (Certified Data Management Professional)','Data Security','hard','A data set is aggregated to counts by emirate and profession, and one cell has a count of one. Publishing it risks','Nothing, since counts are not personal data','A schema violation','Only a performance problem','Re-identification of an individual through a small-cell disclosure','D','A cell of size one identifies a single person by their attribute combination, which is the classic small-cell disclosure risk. Suppression or aggregation thresholds are the standard mitigation.'),
('CDMP (Certified Data Management Professional)','Data Architecture','exam','Which statement about a data lakehouse is accurate?','It stores only unstructured data','It removes the need for data modelling','It replaces governance with schema-on-read','It combines low-cost open-format storage with table-level transactions and schema enforcement','D','A lakehouse adds ACID table semantics and schema management over open storage formats, which is precisely what a raw lake lacks. Modelling and governance obligations do not disappear.'),
('CDMP (Certified Data Management Professional)','Data Governance','exam','Which measure best demonstrates that a governance programme is working?','The number of policies published','The number of governance meetings held','Reduction in defined defects and disputes at the point of use, with owned issues closed to root cause','The size of the governance team','C','Governance is evidenced by measured improvement in the outcomes it exists to protect, not by its own activity volume. Counting policies, meetings and headcount measures effort rather than effect.'),
('CDMP (Certified Data Management Professional)','Data Modeling and Design','exam','Denormalising a reporting table is justified when','Query performance requirements outweigh the update anomalies, and the redundancy is controlled by a repeatable build','It reduces disk usage','Normalisation is optional in all warehouses','The modeller prefers wide tables','A','Denormalisation is a deliberate trade of update integrity for read performance, acceptable when the table is rebuilt by a controlled process rather than updated in place. Preference and disk usage are not engineering justifications.'),
('CDMP (Certified Data Management Professional)','Document and Content Management','hard','A litigation hold arrives while an automated purge job is scheduled to delete matching records tonight. The correct action is','Let the purge run, since it was scheduled before the hold','Archive the records to a personal drive','Delete everything to avoid ambiguity','Suspend disposition for the records in scope of the hold and record the suspension, then resume when the hold is lifted','D','A legal hold overrides the retention schedule for the records in its scope and must be applied before any further disposition. Proceeding with the purge destroys evidence, and moving records to unmanaged storage breaks the chain of custody.')
) as v(certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
where not exists (select 1 from public.certification_exam_question where certification = 'CDMP (Certified Data Management Professional)');

-- ============================== Google Professional Data Engineer (Google exam guide sections) ==============================
insert into public.certification_exam_question
  (certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
select * from (values
('Google Professional Data Engineer','Designing data processing systems','exam','A workload needs sub-10ms lookups by supplier key at very high write throughput, with no ad hoc SQL required. The best managed choice is','Cloud SQL','BigQuery','Bigtable','Cloud Storage','C','Bigtable is designed for low-latency, high-throughput key-based access with a single row key, which matches this access pattern exactly. BigQuery is an analytical engine and Cloud SQL will not sustain that write rate at that latency.'),
('Google Professional Data Engineer','Designing data processing systems','exam','A globally distributed transactional system needs strong consistency and horizontal scale with relational semantics. The right service is','Cloud Spanner','Firestore in Datastore mode','Bigtable','Memorystore','A','Spanner is the managed relational service offering external consistency with horizontal scale across regions. Bigtable and Memorystore are non-relational, and Datastore mode does not provide Spanner''s relational and consistency guarantees.'),
('Google Professional Data Engineer','Designing data processing systems','exam','Which choice reduces BigQuery cost most reliably for a table always filtered by event date and often by country?','Increasing the slot reservation','Partitioning by event date and clustering by country','Adding more indexes','Storing the table as CSV in Cloud Storage','B','Date partitioning prunes whole partitions and clustering co-locates rows so scanned bytes fall, which is what on-demand billing charges for. Slots change capacity, not bytes scanned.'),
('Google Professional Data Engineer','Designing data processing systems','hard','A pipeline must handle events arriving up to two hours late without corrupting hourly aggregates. In Dataflow the correct construct is','Larger machine types','Increasing the number of workers','Processing-time triggers only','Event-time windowing with a watermark, an allowed lateness of two hours and accumulating triggers','D','Event-time windows with allowed lateness assign each event to the hour it happened rather than the hour it arrived, and triggers control emission of updated results. Scaling resources does not change the semantics of late data.'),
('Google Professional Data Engineer','Ingesting and processing the data','exam','Pub/Sub guarantees at-least-once delivery. The subscriber must therefore be','Single-threaded','Idempotent, or must deduplicate on a message attribute or business key','Synchronous','Deployed in one zone only','B','At-least-once delivery means duplicates are normal and correctness must come from the consumer. Idempotent handling or explicit deduplication is the standard defence.'),
('Google Professional Data Engineer','Ingesting and processing the data','exam','A batch of malformed records repeatedly crashes a streaming pipeline. The correct pattern is','Drop the whole window','Retry indefinitely','Route failing elements to a dead-letter destination with the error, and continue processing','Stop the pipeline until the source is fixed','C','A dead-letter path isolates poison records for later inspection while the pipeline keeps making progress. Infinite retries and full stops turn one bad record into an outage.'),
('Google Professional Data Engineer','Ingesting and processing the data','exam','Which is the most cost-effective way to load a daily 50 GB CSV export into BigQuery?','Stream every row through the streaming insert API','Use bq load or a batch load job from Cloud Storage','Insert rows one at a time with SQL','Load into Cloud SQL and federate','B','Batch loads from Cloud Storage are free of ingest charges and are designed for bulk files. Streaming inserts are billed per row and are intended for low-latency arrival, not daily bulk.'),
('Google Professional Data Engineer','Ingesting and processing the data','hard','A Dataflow streaming job shows rising system lag and one key receiving most elements after a GroupByKey. The correct diagnosis and fix is','Insufficient disk, so increase disk size','Data skew on a hot key, mitigated by adding a salt to the key or using a combiner to pre-aggregate','Network congestion, so change the region','A coding error in the windowing function','B','Concentration of elements on one key serialises work on one worker regardless of how many workers exist, which is classic hot-key skew. Key salting or combiner-based pre-aggregation spreads the work.'),
('Google Professional Data Engineer','Storing the data','hard','Data must be readable within milliseconds for 30 days and then kept for seven years at lowest cost, accessed once or twice a year. The right Cloud Storage design is','Standard class throughout','Nearline throughout','Standard with a lifecycle rule transitioning to Archive after 30 days','Coldline immediately','C','Lifecycle management moves objects to a cheaper class once the hot access window ends, and Archive suits access once or twice a year. Keeping everything Standard overpays and starting in Coldline overpays for retrieval during the hot window.'),
('Google Professional Data Engineer','Storing the data','exam','Which BigQuery feature lets an analyst see a table as it stood two days ago after an accidental overwrite?','Table snapshots taken every hour','Time travel over the configured window, using FOR SYSTEM_TIME AS OF','Cloud Storage versioning','A BigQuery materialised view','B','BigQuery time travel exposes historical versions of a table within the configured retention window via FOR SYSTEM_TIME AS OF. Storage versioning applies to objects, not to BigQuery tables.'),
('Google Professional Data Engineer','Storing the data','exam','A Bigtable row key of supplier_id where ids are sequential integers will most likely cause','Hotspotting on a small number of tablets, because sequential keys write to the end of the key space','Excessive storage cost','Loss of consistency','Failure to compact','A','Monotonically increasing row keys concentrate writes at one end of the sorted key space, overloading a single tablet server. Reversing, hashing or field-promoting the key distributes the load.'),
('Google Professional Data Engineer','Storing the data','hard','A table must be shared with a partner who may see only rows for their own supplier account, using standard BigQuery features. The best approach is','Copy a filtered table for each partner nightly','Grant dataset-level viewer and trust the partner''s queries','An authorised view or row-level access policy that filters on the caller''s identity','Export to CSV and email it','C','Authorised views and row-level access policies enforce the filter inside BigQuery based on the querying identity, so no unfiltered copy exists. Nightly copies multiply storage and drift, and dataset-level grants expose every row.'),
('Google Professional Data Engineer','Preparing and using data for analysis','exam','An analyst repeatedly runs the same expensive daily aggregation. The most appropriate optimisation is','Increase the query timeout','A scheduled query or materialised view that maintains the aggregate incrementally','Add ORDER BY to the query','Convert the table to an external table','B','Materialised views and scheduled aggregations compute the result once and let readers scan far fewer bytes. External tables and ORDER BY increase, not reduce, work.'),
('Google Professional Data Engineer','Preparing and using data for analysis','exam','Which BigQuery SQL construct correctly counts distinct suppliers exactly, rather than approximately?','APPROX_COUNT_DISTINCT(supplier_id)','HLL_COUNT.INIT(supplier_id)','COUNT(supplier_id)','COUNT(DISTINCT supplier_id)','D','COUNT(DISTINCT ...) returns an exact distinct count, while the approximate functions trade accuracy for speed and memory. A plain COUNT counts rows, not distinct entities.'),
('Google Professional Data Engineer','Preparing and using data for analysis','exam','A funnel query joins RFQs to quotes and returns more RFQ rows than exist. The most likely cause is','Fan-out from a one-to-many join, requiring aggregation before joining or COUNT(DISTINCT) on the RFQ key','A missing WHERE clause on the date','An incorrect partition filter','A stale materialised view','A','Joining a parent to a child table multiplies parent rows by the number of matching children, which inflates any count taken afterwards. Pre-aggregating the child side or counting distinct parent keys restores the grain.'),
('Google Professional Data Engineer','Preparing and using data for analysis','hard','A cohort retention query must attribute each supplier to the week they registered and then measure activity in later weeks. The most robust SQL shape is','A single self-join on the activity table with no date anchoring','A cohort CTE holding one row per supplier with the registration week, joined to activity, aggregated by cohort week and week offset','A window function over activity partitioned by day','A UNION of one query per week','B','Fixing each supplier''s cohort once in a dedicated CTE guarantees a stable denominator, and joining activity by week offset produces the triangle. Self-joins without a fixed anchor let a supplier appear in several cohorts.'),
('Google Professional Data Engineer','Operationalising machine learning models','exam','BigQuery ML is the appropriate choice when','The team wants a custom PyTorch architecture','The data lives in BigQuery and a standard model such as logistic regression or boosted trees will do, keeping the data in place','Sub-millisecond online serving is required','The training data is unstructured video','B','BigQuery ML lets analysts train standard model families with SQL on data already in BigQuery, avoiding movement and extra tooling. Custom architectures, unstructured media and online serving belong to Vertex AI.'),
('Google Professional Data Engineer','Operationalising machine learning models','exam','Vertex AI Feature Store''s primary benefit for a production model is','Cheaper storage than BigQuery','A shared feature definition served consistently to training and online inference, reducing training-serving skew','Automatic hyperparameter tuning','Model explainability','B','A feature store exists to give the same computed feature to both the training job and the online request path. Tuning and explainability are separate Vertex capabilities.'),
('Google Professional Data Engineer','Operationalising machine learning models','exam','A deployed model''s inputs drift while labels arrive 45 days late. The right monitoring configuration is','Wait for labels before monitoring anything','Alert only on prediction latency','Enable input feature skew and drift monitoring now, with performance monitoring added once labels land','Retrain daily regardless','C','Input monitoring is available immediately and is the only early signal when labels are delayed by weeks. Performance monitoring is added later without discarding the early warning.'),
('Google Professional Data Engineer','Operationalising machine learning models','hard','A model trained on features computed with a 24-hour lookback is served with features computed with a 1-hour lookback. The consequence is','Faster inference with no accuracy cost','Only a storage saving','Improved freshness that always improves accuracy','Training-serving skew: the serving feature distribution differs from training, so predictions degrade unpredictably','D','The same named feature computed over a different window is a different variable, so the model receives inputs it never learned on. Sharing one transformation definition across training and serving is the control.'),
('Google Professional Data Engineer','Maintaining and automating data workloads','exam','Which service best orchestrates a dependency graph of BigQuery, Dataflow and Cloud Storage steps with retries and backfills?','Cloud Scheduler alone','Cloud Composer, the managed Apache Airflow service','Cloud Functions triggered by a timer','Manual execution from a notebook','B','Composer provides DAG-based dependencies, retries, backfill and observability across services, which a simple timer cannot. Cloud Scheduler fires a job but does not model dependencies or backfills.'),
('Google Professional Data Engineer','Maintaining and automating data workloads','exam','A nightly job silently produced zero rows for five days before anyone noticed. The strongest preventive control is','A data freshness and row-count assertion in the pipeline that fails the run and alerts when output falls outside expectation','A longer job timeout','More log verbosity','A weekly manual check','A','An assertion that fails the run converts a silent success into a loud failure at the moment it happens. Logs and manual checks depend on someone looking.'),
('Google Professional Data Engineer','Maintaining and automating data workloads','exam','To reduce cost for a large, sporadic Dataproc batch workload, the most effective change is','Use ephemeral, autoscaling clusters with preemptible secondary workers, created per job and deleted after','Run a permanent large cluster','Move to the largest machine type available','Disable autoscaling','A','Job-scoped clusters stop paying for idle capacity, and preemptible secondary workers cut the price of fault-tolerant batch work. A permanent cluster pays around the clock for sporadic use.'),
('Google Professional Data Engineer','Maintaining and automating data workloads','hard','A backfill must reprocess 18 months of daily partitions without disturbing the live nightly run. The safest approach is','Reprocess into a separate staging target with bounded parallelism, validate, then atomically swap or write partition by partition with the nightly job holding priority','Pause the nightly job for the duration of the backfill','Run both at full concurrency and let the platform arbitrate','Delete and rebuild the table in place','A','Isolating the backfill output and swapping only after validation means the live table is never in a half-rebuilt state, and bounding parallelism protects shared capacity. Rebuilding in place leaves a window where consumers read incomplete data.'),
('Google Professional Data Engineer','Ensuring solution quality','exam','Which practice best proves a change to a transformation did not alter historical results?','A code review by a second engineer','A unit test on one row','Reprocessing a fixed historical sample and diffing outputs against the stored expected results','Increasing the log level','C','A golden-dataset regression diff measures the actual behaviour of the new code against known-correct output. Reviews and single-row tests can pass while aggregate behaviour changes.'),
('Google Professional Data Engineer','Ensuring solution quality','exam','Sensitive personal data must be discovered and masked before analysts query a landing dataset. The appropriate service is','Cloud DLP, now Sensitive Data Protection, for inspection and de-identification','Cloud Armor','Identity-Aware Proxy','Cloud CDN','A','Sensitive Data Protection inspects content for personal data and applies de-identification transformations such as masking and tokenisation. The other services protect network and application access rather than content.'),
('Google Professional Data Engineer','Ensuring solution quality','exam','Which IAM configuration follows least privilege for an analyst who must query but never modify a dataset?','roles/bigquery.admin on the project','roles/editor on the project','roles/bigquery.dataViewer on the dataset plus roles/bigquery.jobUser on the project','roles/owner on the dataset','C','Data viewer on the specific dataset grants read of that data only, and job user allows running queries without granting any write. Admin, editor and owner all confer modification rights the role does not need.'),
('Google Professional Data Engineer','Ensuring solution quality','hard','A disaster recovery requirement states RPO of one hour and RTO of four hours for the analytics warehouse. Which design satisfies it most directly?','Daily exports to a bucket in the same region','Relying on BigQuery''s internal durability alone','Cross-region dataset replication or hourly incremental copies to a second region, with a tested restore runbook meeting the four-hour target','Weekly snapshots retained for a year','C','An RPO of one hour requires copies no more than an hour old in an independent failure domain, and an RTO of four hours requires a rehearsed restore. Daily or weekly copies exceed the RPO, and internal durability does not address regional loss.'),
('Google Professional Data Engineer','Designing data processing systems','exam','For a marketplace event schema that must add optional fields over time without breaking existing consumers, the best format choice is','CSV with positional columns','Fixed-width text','A schema-registered format such as Avro or Protocol Buffers with backward-compatible field addition','Pickled Python objects','C','Schema-registered binary formats define compatibility rules so that adding optional fields leaves old readers working. Positional and fixed-width text formats break as soon as the layout changes.'),
('Google Professional Data Engineer','Ingesting and processing the data','exam','Exactly-once processing in Dataflow with Pub/Sub is achieved primarily through','Disabling autoscaling','Writing to Cloud Storage instead of BigQuery','Setting a very long acknowledgement deadline','Deduplication on the Pub/Sub message id combined with Dataflow''s checkpointed, deterministic execution','D','Dataflow combines message deduplication with checkpointed state so that retried work does not double-count. Acknowledgement deadlines and sink choice do not by themselves give exactly-once semantics.'),
('Google Professional Data Engineer','Preparing and using data for analysis','exam','A significance test on an A/B experiment is run per country, per device and per channel until one is significant. The result is','Valid, because each test is correct in isolation','Invalid only if the samples overlap','Valid if the sample sizes are equal','Multiple comparisons inflating the false discovery rate; a correction or a pre-registered primary metric is required','D','Running many tests makes at least one significant result likely by chance alone, which is the multiple comparisons problem. A pre-registered primary metric or a formal correction restores the stated error rate.'),
('Google Professional Data Engineer','Storing the data','exam','Which is the correct reason to avoid many small files in a Cloud Storage-backed table?','Small files cost more per gigabyte','Small files break lifecycle rules','Small files cannot be encrypted','Per-file listing and open overhead dominates, degrading scan performance; compaction into larger files fixes it','D','Metadata and open costs are per object, so thousands of tiny files spend more time on overhead than on reading bytes. Compaction restores throughput without changing the data.'),
('Google Professional Data Engineer','Maintaining and automating data workloads','exam','A DAG task occasionally fails from a transient API error. The right Airflow configuration is','Bounded retries with exponential backoff and an alert only after retries are exhausted','Unlimited retries with no alerting','No retries so failures are always visible','A manual restart procedure','A','Bounded retries with backoff absorb transient faults without hiding persistent ones, and alerting after exhaustion keeps the signal meaningful. Unlimited retries mask real outages, and no retries page humans for self-healing errors.'),
('Google Professional Data Engineer','Operationalising machine learning models','exam','Which evaluation split is correct for a model predicting next-month supplier churn?','A random split of all supplier-months','Training and evaluating on the same months','A split stratified by supplier id only','A time-based split training on earlier months and evaluating on later months','D','Only a forward-in-time split reproduces the deployed task of predicting an unseen future from a known past. Random splits let contemporaneous information leak across the boundary.'),
('Google Professional Data Engineer','Ensuring solution quality','exam','A pipeline writes to BigQuery and half the rows fail schema validation. Which behaviour is most defensible for a financial dataset?','Load the valid rows and silently drop the rest','Coerce failing values to null and continue','Fail the load atomically, quarantine the batch and alert, so no partial state is published','Truncate the table and reload later','C','A partially loaded financial table is worse than a missing one because consumers cannot tell it is incomplete. Atomic failure with quarantine preserves correctness and makes the defect visible.'),
('Google Professional Data Engineer','Designing data processing systems','hard','A requirement states "under one second from event to dashboard, 10,000 events per second, with exact aggregates". Which combination is the strongest fit?','Cloud Scheduler and bq load every minute','Cloud SQL with triggers and a BI tool polling every second','Dataproc batch jobs every five minutes','Pub/Sub into a Dataflow streaming job maintaining aggregates, materialised to BigQuery or Bigtable for the dashboard','D','Only a streaming path sustains that rate within a one-second budget while maintaining aggregates incrementally. Minute-level batch loads and five-minute Dataproc jobs cannot meet the latency, and Cloud SQL triggers will not sustain the throughput.'),
('Google Professional Data Engineer','Storing the data','exam','Customer-managed encryption keys are required for a dataset. The practical operational obligation this creates is','No obligation; Google manages rotation','Mandatory multi-region storage','A change to the table schema','Key lifecycle management, because destroying or disabling the key renders the data unreadable','D','With customer-managed keys the customer owns availability of the key, so key destruction or disablement permanently blocks access to the data. Rotation and access to the key ring become operational responsibilities.'),
('Google Professional Data Engineer','Preparing and using data for analysis','exam','SELECT * on a wide BigQuery table for a dashboard that shows three columns is a problem because','It scans every column, so on-demand cost and latency scale with columns not used','It always returns wrong results','It bypasses partition pruning','It disables caching','A','BigQuery is columnar and bills on-demand queries by bytes scanned, so selecting unused columns is paid for and slows the query. Naming the three columns removes that cost.'),
('Google Professional Data Engineer','Ingesting and processing the data','exam','A source system emits the same business event to two topics during a migration. The consumer should','Deduplicate on a stable business event key across both sources during the overlap window','Process both and accept double counting','Randomly choose one message','Stop consuming until the migration ends','A','A stable business key lets the consumer recognise the same event from either source and process it once. Accepting duplicates corrupts the aggregates the migration was supposed to preserve.'),
('Google Professional Data Engineer','Ensuring solution quality','hard','An audit asks which service account read a specific BigQuery table on a given day. The correct source of truth is','The BigQuery job history of the current user','The Dataflow job graph','The table''s last modified timestamp','Cloud Audit Logs data access logs for BigQuery, if data access logging was enabled at the time','D','Data access audit logs record who read what and when, but only for the period during which they were enabled. Job history is scoped to the caller, and timestamps record writes rather than reads.')
) as v(certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
where not exists (select 1 from public.certification_exam_question where certification = 'Google Professional Data Engineer');

-- ============================== Microsoft PL-300 Power BI Data Analyst (PL-300 skills measured) ==============================
insert into public.certification_exam_question
  (certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
select * from (values
('Microsoft PL-300 Power BI Data Analyst','Prepare the data','exam','A Power Query step uses a native SQL statement written by hand. The most likely consequence is','Faster refresh in every case','Query folding stops at that step, so later transformations run locally instead of at the source','Incremental refresh becomes mandatory','DirectQuery is enabled automatically','B','A hand-written native query blocks folding, so Power Query can no longer push subsequent steps back to the source. Everything after that step is evaluated in the mashup engine, which is usually slower.'),
('Microsoft PL-300 Power BI Data Analyst','Prepare the data','exam','A 200-million-row fact table refreshes for hours each night although only the last three days change. The correct configuration is','Import the whole table with a larger gateway','Incremental refresh with RangeStart and RangeEnd parameters and a folding source','Switch every table to DirectQuery','Disable the data load for the table','B','Incremental refresh partitions the table by date and refreshes only recent partitions, provided the source query folds so the range filter is pushed down. Larger hardware does not reduce the volume being reprocessed.'),
('Microsoft PL-300 Power BI Data Analyst','Prepare the data','exam','A column contains "AED 1,250.00" as text and must be used in arithmetic. In Power Query the correct approach is','Change the type to whole number directly','Use a measure to cast it at query time','Leave it as text and rely on implicit conversion','Remove the currency prefix and thousands separator, then change type to decimal number with the correct locale','D','Type conversion fails while non-numeric characters remain, so the text must be cleaned first and converted with the right locale for the decimal separator. Implicit conversion is unreliable and pushes the cost to every visual.'),
('Microsoft PL-300 Power BI Data Analyst','Prepare the data','hard','Two source tables must be combined; one has 40 million rows and the other 30. The merge is slow and the source is a folding SQL database. The most effective fix is','Buffer both tables with Table.Buffer','Restructure so the merge folds to the source, keeping the join as a database join and removing steps that break folding','Increase the gateway memory','Convert both to DirectQuery','B','A merge that folds executes as a database join on the server, where the join is cheap and only the result travels. Table.Buffer explicitly breaks folding, and memory does not fix an operation that should never have run locally.'),
('Microsoft PL-300 Power BI Data Analyst','Model the data','hard','A fact table has both an order date and a ship date and users want to slice by either with one date table. The correct modelling technique is','Two separate date tables with no relationships','One active relationship on order date, an inactive relationship on ship date, activated in measures with USERELATIONSHIP','A bidirectional relationship on both columns','A calculated column copying the ship date onto the date table','B','Only one relationship between two tables can be active, so the second role is expressed as an inactive relationship invoked by USERELATIONSHIP inside the measure. Duplicating date tables fragments slicers and bidirectional filtering creates ambiguity.'),
('Microsoft PL-300 Power BI Data Analyst','Model the data','hard','A model has a 12-million-row fact table and eight small dimensions in a star schema, but a modeller proposes flattening everything into one wide table. The main drawback is','Nothing; flat tables are always faster','It always breaks refresh','Column cardinality and repetition rise, hurting compression and model size, and reusable dimension filtering is lost','DAX will no longer work','C','The VertiPaq engine compresses low-cardinality dimension columns very effectively, and repeating them across every fact row inflates the model. A star schema also keeps filter logic simple and reusable.'),
('Microsoft PL-300 Power BI Data Analyst','Model the data','exam','Which DAX expression correctly returns sales for the same period last year, given a marked date table?','CALCULATE([Sales], SAMEPERIODLASTYEAR(Date[Date]))','CALCULATE([Sales], Date[Year] = YEAR(TODAY()) - 1)','SUM(Sales[Amount]) - 1','[Sales] * 0.9','A','SAMEPERIODLASTYEAR shifts the existing filter context back one year and works with any selected period, which is what the time intelligence functions require a marked date table for. A hard-coded year filter ignores the user''s current selection.'),
('Microsoft PL-300 Power BI Data Analyst','Model the data','hard','A measure written as SUMX(Sales, Sales[Qty] * RELATED(Product[Price])) is slow on 50 million rows. The most effective optimisation is','Wrap the measure in CALCULATE','Convert the row-by-row lookup into a materialised column or pre-computed amount at the source, so the measure becomes a simple SUM','Add a bidirectional relationship','Replace SUMX with SUMMARIZE','B','Row-context lookups across a relationship for 50 million rows are expensive to evaluate repeatedly, whereas a stored amount column compresses well and sums in the storage engine. Moving the multiplication upstream converts an iterator into a straight aggregation.'),
('Microsoft PL-300 Power BI Data Analyst','Model the data','exam','What is the difference between a calculated column and a measure in terms of evaluation?','A calculated column is computed at refresh and stored per row; a measure is evaluated at query time in filter context','Both are stored in the model identically','A measure is computed at refresh and stored','Calculated columns cannot reference other tables','A','Calculated columns materialise once per row during refresh and occupy memory, while measures are evaluated dynamically against the current filter context. Choosing the wrong one either bloats the model or produces static results.'),
('Microsoft PL-300 Power BI Data Analyst','Model the data','exam','Setting a relationship''s cross-filter direction to Both between two dimensions in a star schema commonly causes','Faster queries in all cases','Ambiguous filter paths and potentially incorrect or non-deterministic results','Automatic data compression','Removal of the need for a date table','B','Bidirectional filtering can create multiple paths between tables, which the engine must disambiguate and which can silently change results. Single-direction filtering from dimension to fact with CROSSFILTER where genuinely needed is the safer default.'),
('Microsoft PL-300 Power BI Data Analyst','Model the data','exam','A DAX measure must ignore all slicers except the country slicer. The correct pattern is','CALCULATE([Sales], ALL(Sales))','CALCULATE([Sales], REMOVEFILTERS())','CALCULATE([Sales], ALLEXCEPT(Supplier, Supplier[Country]))','CALCULATE([Sales], VALUES(Supplier[Country]))','C','ALLEXCEPT removes filters from the table except on the listed columns, which is precisely "ignore everything but country". REMOVEFILTERS with no argument would drop the country filter as well.'),
('Microsoft PL-300 Power BI Data Analyst','Model the data','hard','A many-to-many relationship between suppliers and categories produces inflated totals. The most robust model change is','Set the relationship to bidirectional','Use a bridge table at the correct grain with single-direction relationships, and aggregate the measure at that grain','Hide the totals row','Use DISTINCTCOUNT everywhere','B','A bridge table expresses the many-to-many explicitly and lets the measure be defined at a grain where the aggregation is correct. Bidirectional filtering and hiding totals conceal the double counting rather than removing it.'),
('Microsoft PL-300 Power BI Data Analyst','Visualize and analyze the data','exam','A stakeholder wants to see whether RFQ volume changed after a fee change on a specific date. The clearest visual is','A pie chart of RFQ volume by month','A line chart over time with a reference line at the change date and, ideally, a comparison series','A treemap by category','A donut chart split before and after','B','Change over time with an intervention is read from a time series with the event marked, and a comparison series guards against attributing a general trend to the change. Part-to-whole charts cannot show timing at all.'),
('Microsoft PL-300 Power BI Data Analyst','Visualize and analyze the data','exam','A bar chart of conversion rate starts its axis at 40 percent, making a 2-point difference look enormous. The professional obligation is','Keep it, since the chart is technically accurate','Start the axis at zero for the length-encoded bars, or switch to a dot plot if the zoomed range is genuinely needed and label it','Change to a 3-D bar chart','Remove the axis labels','B','Bars encode value by length, so a truncated baseline misstates the ratio the reader perceives. A dot plot legitimately supports a zoomed range because position, not length, carries the value.'),
('Microsoft PL-300 Power BI Data Analyst','Visualize and analyze the data','exam','Which Power BI feature lets a user click a supplier in one report and open a filtered detail page for that supplier?','Bookmarks','Drillthrough with the supplier field as the drillthrough filter','Sync slicers','A tooltip page','B','Drillthrough passes the selected entity''s filter context to a dedicated page built for that entity. Bookmarks capture states, and sync slicers align existing slicers rather than navigating.'),
('Microsoft PL-300 Power BI Data Analyst','Visualize and analyze the data','hard','A KPI card shows 15 percent conversion, but the underlying denominator for one segment is 7 RFQs. The best analytical practice is','Suppress or annotate rates computed on small denominators, and show the denominator alongside the rate','Show the 15 percent prominently','Round the rate to the nearest 10 percent','Remove the segment from the model','A','A rate over a very small denominator is unstable and invites decisions the data cannot support, so the base must be visible or the value suppressed. Removing the segment hides a real part of the business.'),
('Microsoft PL-300 Power BI Data Analyst','Visualize and analyze the data','exam','The Key Influencers visual reports that "supplier response time is a key influencer of quote acceptance". The correct interpretation is','It is an associative pattern in the data, not evidence of causation','Reducing response time will cause acceptance to rise','The model has proven a causal link','The relationship is spurious by definition','A','Key Influencers surfaces statistical association within the supplied data and cannot control for confounders. A causal claim requires an experiment or a design that identifies the effect.'),
('Microsoft PL-300 Power BI Data Analyst','Visualize and analyze the data','exam','A report page with 30 visuals is slow. Which diagnostic tool identifies the expensive DAX query first?','Performance Analyzer, which records the DAX query and render time for each visual','The Optimize ribbon alone','The Model view','Refresh history in the service','A','Performance Analyzer attributes duration per visual and exposes the generated DAX query for the slowest ones. Model view and refresh history describe structure and refresh, not query cost.'),
('Microsoft PL-300 Power BI Data Analyst','Visualize and analyze the data','exam','Which choice best supports colour-vision-deficient readers comparing four categories?','Red and green as the primary contrast pair','Colour differences alone with no labels','A distinguishable hue and lightness sequence plus direct labelling or patterns','A rainbow gradient across the four categories','C','Varying lightness as well as hue and labelling series directly keeps the chart readable when hue discrimination is impaired. Red-green pairings and rainbow gradients are the classic failure cases.'),
('Microsoft PL-300 Power BI Data Analyst','Visualize and analyze the data','hard','A stacked bar chart is used to compare the trend of one sub-category across months. The perceptual problem is','Only the bottom series has a common baseline, so the middle series'' lengths are hard to compare across bars','Stacked bars cannot show time','Stacked bars require a date table','Stacked bars cannot be coloured','A','Segments above the baseline start at shifting positions, so readers cannot judge their lengths accurately across categories. A line chart or small multiples gives each series its own baseline.'),
('Microsoft PL-300 Power BI Data Analyst','Deploy and maintain assets','exam','Row-level security is defined in the semantic model and users must see only their own region. Which statement is correct?','RLS roles must be created in the model and members assigned in the service or via a security group','RLS is configured only in Power BI Desktop and needs no service configuration','RLS applies to Import mode only','RLS is enforced by hiding visuals','A','Roles with their DAX filters are authored in the model, but membership is assigned where the content is published. Without member assignment the roles exist but filter nobody.'),
('Microsoft PL-300 Power BI Data Analyst','Deploy and maintain assets','exam','A workspace uses Development, Test and Production stages with deployment pipelines. Data source connections differ per stage. The correct mechanism is','Deployment pipeline rules that override parameters or data sources per stage','Manually edit each dataset after deployment','Separate PBIX files maintained by hand','A shared gateway with no configuration','A','Pipeline rules rebind parameters and connections automatically as content is promoted, which keeps the artefact identical across stages. Manual edits reintroduce drift at every deployment.'),
('Microsoft PL-300 Power BI Data Analyst','Deploy and maintain assets','exam','Which workspace role can publish and update reports but cannot add or remove workspace members?','Viewer','Admin','Contributor','Member','C','The Contributor role grants create and update of content without any membership management rights. Member and Admin both confer membership permissions, and Viewer is read-only.'),
('Microsoft PL-300 Power BI Data Analyst','Deploy and maintain assets','hard','A scheduled refresh of an on-premises SQL source fails intermittently with a gateway timeout while succeeding when run manually. The most probable cause and fix is','The report has too many visuals; remove some','Row-level security is misconfigured','Contention during the scheduled window against a long-running command timeout; stagger the schedule and raise the command timeout at the source query','The workspace role is insufficient','C','Manual success and scheduled failure points to load conditions in the scheduled window rather than to permissions or content. Staggering refreshes and setting an explicit command timeout addresses the actual constraint.'),
('Microsoft PL-300 Power BI Data Analyst','Deploy and maintain assets','exam','A certified semantic model is published for reuse. The main benefit is','Faster visuals','Automatic row-level security','Consumers build reports on one governed set of measures and relationships, so definitions do not diverge','Free capacity','C','Endorsement plus a shared model is the mechanism that stops each report author reinventing the definition of a metric. It changes governance and discoverability, not performance or licensing.'),
('Microsoft PL-300 Power BI Data Analyst','Prepare the data','exam','A survey export has one column per question and must be reshaped to one row per respondent per question. The Power Query operation is','Pivot Column','Group By','Unpivot Other Columns','Merge Queries','C','Unpivot converts a wide layout with one column per attribute into an attribute-value pair per row, which is the required long shape. Pivot performs the opposite transformation.'),
('Microsoft PL-300 Power BI Data Analyst','Prepare the data','exam','Which profiling feature in Power Query most directly reveals that 12 percent of a key column is null?','Column quality','Query dependencies','Data source settings','The Applied Steps list','A','Column quality reports the proportion of valid, error and empty values for a column. Dependencies and applied steps describe query structure rather than data condition.'),
('Microsoft PL-300 Power BI Data Analyst','Model the data','exam','A date table is required for time intelligence. Which property must be set for the DAX time intelligence functions to behave correctly?','The table must be sorted ascending','The table must be in DirectQuery mode','The table must be marked as a date table with a contiguous, unique date column','The table must contain only working days','C','Time intelligence assumes a continuous, unique date column marked as the model''s date table, without gaps. A working-days-only table breaks the contiguity those functions rely on.'),
('Microsoft PL-300 Power BI Data Analyst','Model the data','exam','DIVIDE([Won], [Total]) is preferred over [Won] / [Total] because','It is faster in every case','It ignores filter context','It automatically formats as a percentage','It handles division by zero and blank denominators, returning a specified alternate result','D','DIVIDE has built-in handling for a zero or blank denominator and returns the alternate result instead of an error. Formatting and filter context are unaffected.'),
('Microsoft PL-300 Power BI Data Analyst','Visualize and analyze the data','exam','A cohort retention triangle is required: registration month down the rows, months since registration across the columns. The model needs','A months-since-registration column or measure computed as a date difference, used on the columns axis, with registration month on the rows','A single date table only','A bidirectional relationship','A calculated table per cohort','A','The offset between the activity date and the cohort anchor is what forms the columns of a retention triangle. Without that offset, the visual can only show calendar months, not tenure.'),
('Microsoft PL-300 Power BI Data Analyst','Deploy and maintain assets','exam','An analyst wants a colleague to explore a dataset without seeing another region''s rows. The combination required is','Workspace Admin plus a filtered report','Exporting the data to Excel','Viewer role only','Build permission on the semantic model plus row-level security with the colleague in the appropriate role','D','Build permission allows creating new content from the model, while RLS constrains which rows any query returns for that user. Viewer alone cannot explore, and export removes the enforcement entirely.'),
('Microsoft PL-300 Power BI Data Analyst','Prepare the data','hard','A DirectQuery model must join a small local reference list that does not exist in the source. The supported approach is','Import the entire fact table instead','Recreate the list in the source database only','Use Power Query merge against a local file in DirectQuery mode','Use a composite model with the reference list in Import storage mode and the fact in DirectQuery, setting the dimension to Dual where appropriate','D','Composite models allow mixed storage modes, and Dual mode lets a shared dimension serve both Import and DirectQuery paths efficiently. DirectQuery cannot merge against a local file.'),
('Microsoft PL-300 Power BI Data Analyst','Model the data','exam','A model contains a high-cardinality datetime column used only for date-level analysis. The best size optimisation is','Delete the fact table','Add a calculated column of the same value','Convert it to text','Split it into a date column and, if needed, a separate time column, and remove the unused time precision','D','Second-level precision creates millions of distinct values that compress poorly, and splitting or truncating collapses the cardinality. Text conversion makes it larger and unusable for time intelligence.'),
('Microsoft PL-300 Power BI Data Analyst','Visualize and analyze the data','exam','Which visual best answers "how is total quote value distributed across suppliers, and how concentrated is it"?','A single KPI card','A pie chart with 200 slices','A Pareto or sorted bar chart with a cumulative percentage line','A gauge','C','A sorted bar with a cumulative line shows both the individual contributions and the concentration at a glance. A 200-slice pie is unreadable and a card or gauge shows only one number.'),
('Microsoft PL-300 Power BI Data Analyst','Deploy and maintain assets','exam','What is the practical effect of setting a semantic model to a large semantic model storage format on a capacity?','It removes the need for incremental refresh','It disables row-level security','It allows the model to grow beyond the default in-memory limit and supports faster write operations for large models','It converts the model to DirectQuery','C','The large storage format raises the size ceiling and changes how the model is paged in memory on capacity. Refresh strategy and security behaviour are unchanged.'),
('Microsoft PL-300 Power BI Data Analyst','Prepare the data','exam','Sensitive columns must never leave the source. The most appropriate preparation choice is','Import everything and hide the columns in the report','Use a bookmark to hide them','Set the columns to a private data privacy level only','Remove the columns in Power Query at the source-folding step, or exclude them from the source query entirely','D','Hidden columns are still present in the model file and can be read by anyone with model access, so exclusion must happen before import. Privacy levels govern query folding across sources, not data exposure in the model.'),
('Microsoft PL-300 Power BI Data Analyst','Visualize and analyze the data','exam','A report shows conversion rising while every individual segment falls. Before publishing, the analyst should','Publish it as a success story','Change the aggregation to a median','Remove the segment breakdown','Investigate the mix shift causing Simpson''s paradox and present the segment view alongside the total','D','A total that moves against every segment is a mix effect and reporting only the headline would mislead the reader. Showing both the total and the segments is the honest presentation.'),
('Microsoft PL-300 Power BI Data Analyst','Model the data','hard','Two fact tables at different grains, daily budget and transactional actuals, must be compared. The correct pattern is','Join the two fact tables directly on date','Use a bidirectional relationship between the facts','Duplicate the budget rows to transaction grain','Relate both to shared conformed dimensions at the coarsest common grain and compare measures, never joining fact to fact','D','Facts at different grains are compared through shared dimensions at a common grain, which is the standard star-schema pattern. Joining fact to fact or exploding the budget fabricates rows that never existed.'),
('Microsoft PL-300 Power BI Data Analyst','Deploy and maintain assets','exam','A dataset refresh must run eight times a day on shared capacity, where the limit is eight scheduled refreshes daily. The analyst should','Schedule nine refreshes and accept a failure','Refresh manually the rest of the day','Use DirectQuery to bypass the limit without any other consideration','Schedule eight refreshes, or move the workspace to a capacity that permits more frequent refresh','D','Shared capacity enforces the daily refresh limit, so meeting a higher cadence requires premium or Fabric capacity. DirectQuery is a design change with its own performance and source-load consequences, not a simple bypass.'),
('Microsoft PL-300 Power BI Data Analyst','Visualize and analyze the data','exam','A dashboard must let an executive answer "which supplier categories are both large and declining" in one glance. The strongest single visual is','A table of every category and month','A stacked area chart of all categories','A card showing the total decline','A scatter plot of current size against period-over-period change, with quadrants and category labels','D','A scatter of magnitude against change places each category in a quadrant so "large and declining" is a visible region, not a computation the reader must perform. Tables and stacked areas force serial reading or defeat comparison.')
) as v(certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
where not exists (select 1 from public.certification_exam_question where certification = 'Microsoft PL-300 Power BI Data Analyst');

-- ============================== CKM (Certified Knowledge Manager) (KM Institute KM framework) ==============================
insert into public.certification_exam_question
  (certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
select * from (values
('CKM (Certified Knowledge Manager)','Strategy and Governance','hard','A company buys a knowledge platform first and then asks what to put in it. The KM Institute framework says this fails because','The tool was too expensive','No vendor supports every format','Technology is one enabler of a KM strategy that must first define the knowledge, people and processes it serves','Governance should have been outsourced','C','KM frameworks place strategy and the knowledge needs of the business ahead of tooling, with technology enabling the defined processes. A platform without a defined knowledge need has nothing to enable.'),
('CKM (Certified Knowledge Manager)','Strategy and Governance','exam','Which KM objective is written so it can actually be measured?','Become a learning organisation','Improve knowledge sharing','Cut median time for a support agent to find a verified answer from 9 minutes to 3 within two quarters','Encourage a culture of collaboration','C','A measurable objective names the metric, the baseline, the target and the horizon. Aspirations without a metric cannot be evaluated or funded on evidence.'),
('CKM (Certified Knowledge Manager)','Strategy and Governance','exam','A KM programme reports "5,000 articles published" as its headline outcome. The weakness is','It counts output rather than the outcome of knowledge being found and reused to change work','Five thousand is too few','It should count words instead','Articles are the wrong artefact type','A','Volume of content is an activity measure that can rise while findability and reuse fall. Outcome measures track retrieval success, reuse and the work the knowledge changed.'),
('CKM (Certified Knowledge Manager)','People','hard','A community of practice thrives for a year, then goes quiet after its founder leaves. The most structural remedy is','Mandate weekly attendance','Merge it into a reporting line','Replace it with a document repository','Institutionalise the roles the founder held: a rotating facilitator, a defined purpose, and a sponsor with time allocated for participation','D','Communities collapse when their continuity depends on one individual''s discretionary effort rather than on defined, resourced roles. Mandates and repositories address neither the facilitation nor the sponsorship that sustained it.'),
('CKM (Certified Knowledge Manager)','People','exam','Which technique is designed specifically to transfer tacit knowledge from an expert who is about to retire?','Publishing the expert''s file directory','Structured knowledge elicitation and apprenticeship, such as interviews around real cases plus paired working','A satisfaction survey','An org chart update','B','Tacit knowledge lives in judgement applied to situations and transfers through narrated cases and paired practice. Copying files transfers explicit artefacts, not the reasoning behind them.'),
('CKM (Certified Knowledge Manager)','People','exam','An after action review is most effective when it','Assigns blame for the failure','Is run as a blameless comparison of intended versus actual outcome, with causes and specific changes owned by name','Is documented only for the executive team','Happens a year later','B','The AAR method depends on psychological safety to surface the real causes and on named owners for the changes. Blame suppresses disclosure and delay destroys recall.'),
('CKM (Certified Knowledge Manager)','People','exam','Experts refuse to contribute because "documenting takes time I do not have". The most effective intervention is','A poster campaign about sharing','Capture knowledge as a by-product of the work, for example by turning resolved tickets into reviewed articles, and recognise contribution in performance expectations','A mandatory monthly quota of articles','Removing the experts from the process','B','Reducing the marginal cost of contribution and aligning it with recognised performance addresses the actual constraint, which is time. Quotas produce low-quality volume and campaigns change nothing about the cost.'),
('CKM (Certified Knowledge Manager)','Process','hard','A knowledge base has 4,000 articles, 60 percent of which have not been viewed in two years and many of which contradict newer ones. The correct KM process response is','Delete every article older than two years','Buy a better search engine','Institute a review-and-retire lifecycle with owners, review dates and archival, then reconcile contradictions in the surviving set','Merge all articles into one master document','C','Content lifecycle governance is what prevents contradiction and rot, and it requires named owners and scheduled review rather than a one-off purge. Age alone is not evidence of obsolescence, and search cannot resolve contradictory sources.'),
('CKM (Certified Knowledge Manager)','Process','exam','Which sequence correctly describes a knowledge lifecycle?','Retire, create, capture, share','Share, create, capture, apply','Capture, retire, create, share','Create or capture, organise, share, apply, review and retire','D','The lifecycle moves from creation through organisation and sharing to application, then to review and retirement. The other sequences place use or retirement before the knowledge exists.'),
('CKM (Certified Knowledge Manager)','Process','exam','Lessons learned are captured diligently but the same mistakes recur. The missing process step is','More detailed capture templates','Embedding lessons into the operational process, checklists or standards that the next project must follow','A larger lessons repository','A monthly newsletter','B','Lessons change behaviour only when they are built into the artefacts the next team is required to use. Capture without embedding produces an archive of regrets.'),
('CKM (Certified Knowledge Manager)','Process','exam','A peer assist is best used','After a project has failed, to review it','Before or early in a piece of work, to bring experience from others who have done it','Only at the annual planning meeting','As a replacement for project governance','B','Peer assist brings external experience to bear while decisions are still open and cheap to change. Reviewing after the fact is the retrospective or AAR technique instead.'),
('CKM (Certified Knowledge Manager)','Technology','hard','A retrieval system answers questions from the knowledge base but frequently returns confident answers built from a retired article. The primary governance fix is','Increase the number of retrieved passages','Make retrieval respect content lifecycle status and effective dates, and require answers to cite the source article and its version','Lower the similarity threshold','Retrain the embedding model','B','A nearest neighbour is always returned, so the defence against stale answers is metadata governance at retrieval plus citation that lets a reader verify. Tuning retrieval parameters does not tell the system which content is still valid.'),
('CKM (Certified Knowledge Manager)','Technology','exam','A taxonomy and a folksonomy differ in that','A taxonomy is a governed, hierarchical vocabulary; a folksonomy emerges from uncontrolled user tags','A folksonomy is hierarchical and a taxonomy is flat','They are the same','Only taxonomies can be searched','A','Taxonomies are designed and governed for consistency, while folksonomies capture how users actually label things without control. Mature practice uses both, mapping popular tags into the governed vocabulary.'),
('CKM (Certified Knowledge Manager)','Technology','exam','Search analytics show many queries returning zero results. The most valuable use of that data is','Hide the zero-result message','Treat the zero-result queries as a prioritised map of content gaps and missing synonyms','Disable search logging','Increase the result count limit','B','Failed queries are direct evidence of demand that the content and vocabulary do not meet. Treating them as a backlog turns search analytics into a content roadmap.'),
('CKM (Certified Knowledge Manager)','Technology','exam','Metadata is applied inconsistently across contributors. The most durable improvement is','Ask contributors to try harder','Remove metadata requirements','Constrain fields with a governed value list, default what can be inferred automatically, and validate at submission','Add more optional fields','C','Consistency comes from making the correct value the easy or automatic one and validating at the point of entry. Exhortation and additional optional fields both increase variance.'),
('CKM (Certified Knowledge Manager)','Content and Knowledge Assets','hard','Which asset is genuinely a knowledge asset rather than merely information?','A raw export of every support ticket from last year','A list of employee names and titles','A validated troubleshooting playbook that encodes which symptom implies which cause and what to do','A folder of unlabelled scanned invoices','C','A knowledge asset encodes validated understanding that guides action, whereas raw exports and unlabelled files are data or information awaiting interpretation. The distinguishing feature is applicability to a decision.'),
('CKM (Certified Knowledge Manager)','Content and Knowledge Assets','exam','A knowledge asset register should record, at minimum','The file size and format','The owner, purpose, currency or review date, audience and criticality','The author''s job grade','The storage cost','B','A register exists to make each asset''s stewardship and validity visible so it can be governed. Technical attributes say nothing about whether the asset is current or who is accountable.'),
('CKM (Certified Knowledge Manager)','Content and Knowledge Assets','exam','Explicit and tacit knowledge are best distinguished by','Explicit knowledge is codified and transferable as artefacts; tacit knowledge is experiential and transfers mainly through interaction','Explicit knowledge is newer','Tacit knowledge is always more valuable','Explicit knowledge is only found in databases','A','The distinction is about codifiability, which determines the transfer mechanism each requires. Neither type is inherently newer or more valuable.'),
('CKM (Certified Knowledge Manager)','Measurement and KM Metrics','exam','Which KM metric is a genuine outcome measure?','Number of portal logins','Number of documents uploaded','Hours of KM training delivered','Reduction in repeat questions escalated to experts, at constant volume','D','An outcome measure records a change in how the work goes, here fewer escalations for the same demand. Logins, uploads and training hours are activity counts.'),
('CKM (Certified Knowledge Manager)','Measurement and KM Metrics','exam','A KM dashboard shows page views rising 40 percent while first-contact resolution is flat. The honest reading is','Engagement rose but there is no evidence yet that the knowledge changed outcomes','KM is succeeding','KM is failing','Resolution data must be wrong','A','Rising consumption without a change in the outcome metric is exactly an unproven link, not proof either way. Stating that plainly is what distinguishes measurement from advocacy.'),
('CKM (Certified Knowledge Manager)','Measurement and KM Metrics','hard','To attribute a fall in average handling time to a new knowledge base rather than to seasonality or a concurrent training programme, the strongest available design is','Compare this quarter to last quarter','A phased rollout across comparable teams, comparing exposed and not-yet-exposed groups over the same period','A survey asking agents whether the knowledge base helped','A correlation between page views and handling time','B','A staged rollout creates a contemporaneous comparison group that experiences the same season and the same concurrent programmes. Before-and-after comparisons and self-reported surveys cannot separate those influences.'),
('CKM (Certified Knowledge Manager)','KM Culture and Change','exam','Middle managers quietly block a KM initiative that senior leadership sponsors. The most effective response is','Escalate and mandate compliance','Bypass them and work with individual contributors','Understand and address what the change costs them in time, control or measured performance, and align their incentives','Delay the programme by a year','C','Resistance at the middle usually reflects a real conflict with what those managers are measured on. Removing that conflict is more durable than mandating behaviour that their targets punish.'),
('CKM (Certified Knowledge Manager)','KM Culture and Change','exam','Which is the best evidence that a knowledge-sharing culture is taking hold?','Attendance at the KM launch event','Unprompted reuse and improvement of others'' contributions in day-to-day work','The number of KM policies published','A high score on a one-off engagement survey','B','Culture shows in unprompted behaviour that persists without the programme pushing it. Launch attendance and policy counts are inputs, and a single survey score is a snapshot of sentiment.'),
('CKM (Certified Knowledge Manager)','KM Culture and Change','hard','A KM rollout succeeds in a pilot team of eight and fails when extended to 200 people. The most likely cause is','The pilot succeeded on high-touch facilitation and personal relationships that do not scale, without the governed roles, vocabulary and process the larger population needs','The pilot team was unusually intelligent','The technology could not handle 200 users','The larger group is resistant to all change','A','Small pilots are frequently carried by intensive facilitation that cannot be replicated at scale, which hides the absence of structure. Scaling requires the roles, taxonomy and process that the pilot never needed.'),
('CKM (Certified Knowledge Manager)','Strategy and Governance','exam','Knowledge risk assessment for a small company should prioritise','Knowledge concentrated in one person that is critical to a revenue or compliance process','The largest documents','The oldest content','The most frequently viewed pages','A','Knowledge risk is the product of criticality and concentration, so single points of human failure on critical processes rank first. Size, age and popularity do not measure exposure.'),
('CKM (Certified Knowledge Manager)','Process','exam','A knowledge transfer plan for an employee leaving in four weeks should begin with','Identifying the critical decisions and exceptions only that person handles, then transferring those first','Writing every process document','Recording a long unstructured video','Copying their inbox','A','With a fixed and short window, triage by criticality is what determines whether the transfer succeeds. Exhaustive documentation runs out of time before reaching what matters most.'),
('CKM (Certified Knowledge Manager)','Technology','exam','A wiki is chosen over a controlled document system for procedures that carry regulatory obligations. The main governance concern is','Version control, approval and evidence of the effective procedure at a point in time may be insufficient','Wikis cannot store images','Wikis are slower','Wikis cannot be searched','A','Regulated procedures require an auditable record of what was approved and in force on a given date. Open editing without controlled approval and versioning cannot produce that evidence.'),
('CKM (Certified Knowledge Manager)','Content and Knowledge Assets','exam','Two teams maintain overlapping guides that disagree. The right first move is','Publish both and let readers choose','Delete the less popular one','Establish a single accountable owner for the topic and merge into one canonical guide, with the other redirected','Add a disclaimer to both','C','Contradiction is an ownership defect, resolved by naming one accountable owner and one canonical source. Disclaimers and reader choice transfer the problem to the reader.'),
('CKM (Certified Knowledge Manager)','People','exam','Knowledge mapping is primarily used to','Identify where critical knowledge resides, who holds it and where the gaps and dependencies are','Draw the org chart','Rank employees by performance','Catalogue every file in the estate','A','A knowledge map locates expertise and dependency so that risk and gaps become visible and actionable. It is about knowledge distribution, not reporting lines or file inventory.'),
('CKM (Certified Knowledge Manager)','Measurement and KM Metrics','hard','Which measure would best show that a knowledge base is serving self-service rather than merely being read?','Total page views','Average session duration','Deflection: the proportion of sessions that resolve without a subsequent contact, measured against a comparable baseline','Number of articles','C','Deflection measured against a baseline links reading to the avoided contact, which is the outcome self-service exists to produce. Views, duration and article counts do not distinguish successful self-service from confusion.'),
('CKM (Certified Knowledge Manager)','Strategy and Governance','hard','A KM strategy must be defended to a finance committee. The strongest framing is','KM is a strategic necessity that cannot be quantified','The cost of the platform compared with competitor spending','The specific decisions and processes KM will improve, the current cost of getting them wrong, and the measurement plan that will show the change','The number of employees who support the initiative','C','A finance committee funds a quantified problem with a stated measurement plan, not an assertion of necessity. Benchmarking spend and counting supporters answer neither the value nor the evidence question.'),
('CKM (Certified Knowledge Manager)','Process','exam','Which content design change most improves reuse by frontline staff under time pressure?','Task-oriented articles with the answer first, explicit preconditions and short numbered steps','Longer, more comprehensive narrative articles','A single PDF per department','More background history in each article','A','Under time pressure readers scan for the applicable action, so answer-first structure and explicit preconditions determine whether the article is usable. Length and background raise the cost of finding the answer.'),
('CKM (Certified Knowledge Manager)','Technology','exam','An organisation wants agents to see relevant knowledge without searching. The design pattern is','A weekly digest email','A monthly training session','A larger search box','Contextual surfacing: pushing candidate articles into the workflow based on the case attributes the agent is already looking at','D','Delivering knowledge into the tool at the moment of need removes the search step entirely, which is where most self-service is lost. Digests and training are out of context and out of time.'),
('CKM (Certified Knowledge Manager)','KM Culture and Change','exam','Which incentive design is most likely to produce useful contributions rather than gaming?','A prize for the highest number of articles','A public leaderboard of edit counts','A cash bonus per page created','Recognition tied to demonstrated reuse and quality review outcomes of the contributions','D','Rewarding measured usefulness aligns the incentive with the outcome, whereas counting artefacts rewards volume. Volume-based incentives reliably produce low-value content.'),
('CKM (Certified Knowledge Manager)','Content and Knowledge Assets','exam','A knowledge asset must be marked with an effective date and a review date because','It helps with storage planning','It improves the search ranking','It is required by every regulator','Readers and automated retrieval need to know whether the guidance is still in force, and unreviewed content silently becomes wrong','D','Currency metadata is what lets both a human and a retrieval system distinguish valid guidance from something that has quietly expired. Storage and ranking are incidental.'),
('CKM (Certified Knowledge Manager)','Measurement and KM Metrics','exam','A survey asks "how much has our excellent new knowledge base improved your work?" The methodological flaw is','The sample is too small','The survey is anonymous','The scale has too many points','The question is leading and presupposes improvement, biasing responses upward','D','Embedding a positive judgement in the question steers respondents toward agreement regardless of their experience. A neutral wording with a symmetric scale is required for the answer to mean anything.'),
('CKM (Certified Knowledge Manager)','People','exam','Which role in a KM programme is accountable for the accuracy and currency of a specific knowledge domain?','The platform administrator','The executive sponsor','The search engineer','The knowledge steward or domain owner','D','Domain stewardship carries accountability for whether the content in that domain is correct and current. Platform and search roles operate the mechanism, and the sponsor funds and unblocks it.'),
('CKM (Certified Knowledge Manager)','Strategy and Governance','exam','A KM programme and a records management programme both claim ownership of contracts. The correct resolution is','Give both full control','Stop managing contracts under either','Let the larger team win','Define the boundary explicitly: records management owns retention, disposition and evidential control; KM owns findability and reuse of the knowledge derived from them','D','The two disciplines have different obligations over the same artefacts and the boundary must be stated rather than contested. Retention and evidential control are records obligations that KM must not override.'),
('CKM (Certified Knowledge Manager)','KM Culture and Change','exam','The most reliable early signal that a KM change effort is failing is','A drop in platform uptime','Slower page load times','A negative comment in a town hall','Contributors and users quietly reverting to private channels such as direct messages and personal files','D','Reversion to shadow channels shows the sanctioned system is not meeting the real need, and it happens before any metric collapses. Isolated complaints and technical issues are weaker and more ambiguous signals.'),
('CKM (Certified Knowledge Manager)','Technology','hard','An automated assistant answers staff questions from the knowledge base. Which control most directly limits the harm of a wrong answer?','Increasing the model temperature','A longer disclaimer at the bottom of the page','Restricting the assistant to a scope of governed sources, citing the source for every claim, and routing low-confidence or unsourced cases to a human','Answering only in the user''s language','C','Scoping to governed sources with per-claim citation makes a wrong answer verifiable and traceable, and escalation prevents the system from guessing in the cases it handles worst. Disclaimers change nothing about whether the answer is acted on.')
) as v(certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
where not exists (select 1 from public.certification_exam_question where certification = 'CKM (Certified Knowledge Manager)');

-- ============================== MRS Advanced Certificate in Market and Social Research Practice (MRS syllabus) ==============================
insert into public.certification_exam_question
  (certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
select * from (values
('MRS Advanced Certificate in Market and Social Research Practice','Research design','exam','A client asks "why are suppliers not registering?" with no prior evidence. The appropriate first stage is','A 2,000-respondent quantitative survey','Qualitative exploration to surface the range of reasons, followed by quantification of the ones that matter','A conjoint study','A tracking study','B','Exploratory work is needed to discover the candidate explanations before a survey can offer sensible answer options. Quantifying an unexplored space measures only the researcher''s assumptions.'),
('MRS Advanced Certificate in Market and Social Research Practice','Research design','exam','Which design best establishes whether a new onboarding flow increases completion?','A post-launch survey asking users if the flow felt easier','A randomised controlled trial assigning users to the old or new flow','A focus group of users who completed the flow','A comparison of completion before and after launch','B','Random assignment balances known and unknown differences between groups, which is what allows the difference in completion to be attributed to the flow. Before-and-after comparisons absorb every concurrent change.'),
('MRS Advanced Certificate in Market and Social Research Practice','Research design','exam','A tracking study changes its question wording in wave 6. The consequence for the time series is','No consequence if the topic is the same','It is a break in series; wave 6 onward is not directly comparable and must be bridged or annotated','Only the sample size is affected','The earlier waves become invalid','B','Question wording is part of the measurement instrument, so changing it changes what is measured and breaks comparability. A parallel-run bridge or a clear annotation is required.'),
('MRS Advanced Certificate in Market and Social Research Practice','Research design','hard','A client wants to know both the size of a behaviour and the reasoning behind it, with one budget and one timeline. The strongest design is','Two independent studies with unrelated samples','A qualitative study only, since reasoning matters most','A sequential mixed-method design where qualitative findings inform the quantitative instrument, with a qualitative follow-up on the quantitative outliers','A single open-ended question at the end of a survey','C','A sequential design lets each method do what it does well and lets the second stage interrogate what the first revealed. An open-ended tail question yields unstructured text with none of the depth of a qualitative stage.'),
('MRS Advanced Certificate in Market and Social Research Practice','Sampling','exam','A survey is sent only to suppliers who have logged in during the last 30 days, and concludes that suppliers find the platform easy to use. The flaw is','Non-response bias only','Survivorship and coverage bias: those who found it hard are least likely to be in the sample frame','Measurement error','Insufficient sample size','B','The frame excludes exactly the population whose experience would contradict the conclusion, which biases the result regardless of sample size. A frame covering all invited suppliers is required for that claim.'),
('MRS Advanced Certificate in Market and Social Research Practice','Sampling','exam','Quota sampling differs from stratified random sampling because','Quota sampling selects within quotas non-randomly, so sampling error cannot be estimated in the same way','Quota sampling always uses larger samples','Stratified sampling ignores subgroup proportions','They are identical in practice','A','Stratified random sampling uses probability selection within strata, permitting standard error estimation, while quota sampling fills cells by whoever is available. The difference is the selection mechanism, not the size.'),
('MRS Advanced Certificate in Market and Social Research Practice','Sampling','exam','A study achieves a 12 percent response rate. The most important consequence to report is','The result is automatically invalid','The confidence interval is wider than planned only','The risk of non-response bias if respondents differ systematically from non-respondents, which should be assessed and disclosed','That the questionnaire was too long','C','A low response rate matters because of who is missing, not merely because of the count, so the direction and likely size of non-response bias must be assessed and disclosed. Low response does not by itself invalidate a study, but it must not be reported silently.'),
('MRS Advanced Certificate in Market and Social Research Practice','Sampling','hard','Weighting is applied to correct an under-representation of small suppliers, and the largest weight is 14. The correct professional handling is','Apply the weights without comment','Report the effective sample size and design effect, consider trimming extreme weights, and disclose the weighting scheme','Discard the weights entirely','Increase all weights proportionally','B','Extreme weights inflate variance, so the effective sample size and design effect must be reported for the precision claim to be honest. Trimming with disclosure is standard practice; silent weighting is not.'),
('MRS Advanced Certificate in Market and Social Research Practice','Sampling','exam','An online panel is used to represent all UAE businesses. The principal limitation is','Panels are always too small','Panel members are self-selected volunteers, so coverage and self-selection bias remain even after demographic weighting','Panels cannot ask open questions','Panels have no incentives','B','Weighting can align observed demographics but cannot repair unobserved differences between volunteers and non-volunteers. That residual self-selection is the structural limitation of panel research.'),
('MRS Advanced Certificate in Market and Social Research Practice','Sampling','exam','To detect a 5 percentage point difference between two groups with reasonable power, the researcher needs','Any sample above 100 per group','A power calculation specifying the baseline rate, the effect size, alpha and desired power, which determines the required n per group','The same n as the last study','A larger sample only if the difference is not found','B','Sample size follows from the effect to be detected, the baseline, the significance level and the power target. Reusing a previous n or increasing n after a null result are both post hoc and unsound.'),
('MRS Advanced Certificate in Market and Social Research Practice','Data collection','exam','Which question is fit for a quantitative questionnaire?','Do you agree that our excellent service and fast delivery meet your needs?','Would you not disagree that pricing is unclear?','How satisfied are you with the time taken to receive a quote? (five-point scale from very dissatisfied to very satisfied)','Rate our service and pricing on one scale','C','A sound item asks about one construct, in neutral language, with a labelled symmetric scale. The others are leading, double-negative, or double-barrelled.'),
('MRS Advanced Certificate in Market and Social Research Practice','Data collection','exam','Question order effects are best controlled by','Asking all sensitive questions first','Randomising or rotating the order of items within a battery and placing general items before specific ones','Using the same order for every respondent always','Removing all scales','B','Rotation distributes order effects across respondents rather than letting them bias a single item, and general-before-specific avoids priming. A fixed order concentrates the bias.'),
('MRS Advanced Certificate in Market and Social Research Practice','Data collection','exam','Interviewer effects are a particular risk in','Self-completion online surveys','Face-to-face or telephone interviews on sensitive topics, where respondents adjust answers toward perceived approval','Passive behavioural data collection','Automated web analytics','B','Social desirability is amplified when a human interviewer is present, especially on sensitive subjects. Self-completion and passive modes remove the interviewer from the response process.'),
('MRS Advanced Certificate in Market and Social Research Practice','Data collection','hard','A mixed-mode study collects half the sample online and half by telephone, and the two modes differ by 9 points on a satisfaction item. The correct interpretation is','Telephone respondents are more satisfied','The modes must be combined and averaged without comment','A mode effect is confounded with any true difference; the design should have included a mode-effect check and the finding must be reported by mode','The online data should be discarded','C','Measurement differs between modes, so a raw gap cannot be attributed to the population without a design that separates mode from sample. Reporting by mode is the minimum honest treatment.'),
('MRS Advanced Certificate in Market and Social Research Practice','Ethics and the MRS Code of Conduct','exam','A client asks for the names and contact details of survey respondents who rated them poorly, so they can follow up. Under the MRS Code the researcher must','Provide the details, since the client paid for the research','Provide the details only for negative respondents','Refuse, unless respondents gave informed consent for their identifiable data to be passed to the client for that purpose','Provide anonymised details that can still be matched','C','Respondent confidentiality is fundamental and identifiable data may be disclosed only with informed, specific consent for that use. Pseudonymised data that can still be matched is identifiable in practice.'),
('MRS Advanced Certificate in Market and Social Research Practice','Ethics and the MRS Code of Conduct','exam','Selling under the guise of research, sometimes called sugging, is','Acceptable if the questions are genuine','Prohibited, because it misrepresents the purpose of the contact and damages the integrity of research','Acceptable with a short disclaimer','Permitted for existing customers','B','The Code requires that research contacts be for research purposes and not be used to sell, because the deception undermines participation in genuine research. A disclaimer does not cure the misrepresentation.'),
('MRS Advanced Certificate in Market and Social Research Practice','Ethics and the MRS Code of Conduct','exam','Informed consent for research participation requires that the participant knows','The identity of the research agency, the general purpose, how their data will be used and that participation is voluntary and may be withdrawn','Only the length of the interview','The client''s name in every case','The full questionnaire in advance','A','Consent is informed when the participant understands who is asking, why, what happens to their data and that they may decline or withdraw. Client identity may sometimes be withheld, and prior sight of the whole instrument is not required.'),
('MRS Advanced Certificate in Market and Social Research Practice','Ethics and the MRS Code of Conduct','hard','A researcher discovers that a fieldwork subcontractor fabricated 40 interviews. The Code-compliant response is','Remove the 40 and deliver the rest without telling the client','Deliver everything and note it in an appendix','Ask the subcontractor to redo them quietly','Inform the client, remove and disclose the affected data, assess the impact on the findings and take action with the subcontractor','D','Data fabrication is a fundamental breach that affects the validity of the deliverable, and the client cannot judge the findings without knowing. Concealment compounds the breach.'),
('MRS Advanced Certificate in Market and Social Research Practice','Ethics and the MRS Code of Conduct','exam','Research with children under 16 in a commercial context generally requires','Consent from a parent or responsible adult in addition to the child''s own assent, with the topic and method appropriate to their age','Nothing beyond a shorter questionnaire','Only the school''s permission','The same process as for adults','A','Children cannot give legally effective consent alone, so a responsible adult must consent while the child''s own willingness is still respected. Method and content must also be age-appropriate.'),
('MRS Advanced Certificate in Market and Social Research Practice','Ethics and the MRS Code of Conduct','exam','Under the UAE Personal Data Protection Law, a research dataset containing named respondents is','Personal data, requiring a lawful basis, purpose limitation and respect for data subject rights','Outside the scope because it is research','Personal data only if it includes financial details','Exempt if it is stored outside the UAE','A','Named individuals constitute personal data regardless of the research purpose, so a lawful basis and purpose limitation apply. Storage location does not change whether the data is personal.'),
('MRS Advanced Certificate in Market and Social Research Practice','Analysis and interpretation','exam','A crosstab shows 68 percent of respondents in a segment agree, based on 22 respondents. The report should','Present the number with the base clearly flagged as low, or report it as indicative only rather than as a percentage','Present 68 percent as a headline finding','Round it to 70 percent','Exclude the segment silently','A','Percentages on very small bases are unstable and reporting them as headline figures invites decisions the data cannot support. Flagging or suppressing low bases is standard practice.'),
('MRS Advanced Certificate in Market and Social Research Practice','Analysis and interpretation','exam','A significance test at the 95 percent level returns p = 0.04 for a 2-point difference. The correct statement is','The difference is important','There is a 96 percent chance the finding is true','The difference is unlikely under the null hypothesis at the chosen level, but statistical significance is not the same as practical importance','The null hypothesis is proven false','C','A p value is a statement about data under the null hypothesis, not about the probability that a hypothesis is true, and it says nothing about magnitude. A 2-point difference may be significant and still commercially irrelevant.'),
('MRS Advanced Certificate in Market and Social Research Practice','Analysis and interpretation','exam','Net Promoter Score falls from 30 to 24 with a sample of 300 in each wave. Before reporting a decline the analyst should','Report the 6-point fall as a decline','Change the scale','Report it only if the client expects a decline','Test whether the change exceeds sampling error, given that NPS is a difference of two proportions and has a wide interval at n = 300','D','NPS combines two proportions, so its sampling variability is larger than a single proportion at the same n. A 6-point movement at 300 per wave may sit comfortably within noise.'),
('MRS Advanced Certificate in Market and Social Research Practice','Analysis and interpretation','hard','Segmentation produces five clusters, but re-running the analysis on a random half of the data produces different segments. The correct conclusion is','The segmentation is unstable and should not be used for targeting until it replicates on holdout data','Use the first solution because it was computed on more data','Increase the number of clusters','Report both solutions to the client as alternatives','A','A segmentation that does not replicate on a holdout is describing noise rather than structure in the population. Stability testing is a prerequisite for operational use.'),
('MRS Advanced Certificate in Market and Social Research Practice','Analysis and interpretation','hard','Verbatim comments from 15 depth interviews are counted and reported as "60 percent of participants said price was a problem". The methodological error is','Quantifying qualitative data from a small purposive sample as if it were representative','Nothing; the count is accurate','Using percentages at all','Interviewing only 15 people','A','Qualitative samples are purposive and not designed to support population estimates, so percentages imply a precision and generalisability the design cannot deliver. Reporting themes and their range is the appropriate treatment.'),
('MRS Advanced Certificate in Market and Social Research Practice','Analysis and interpretation','exam','A driver analysis regresses overall satisfaction on eight highly correlated attribute ratings. The main risk is','Multicollinearity making individual coefficients unstable and their signs unreliable','Too few observations','Non-response bias','Interviewer effects','A','Highly correlated predictors inflate coefficient variance so that individual importance estimates flip with small data changes. Relative importance methods or dimension reduction address it.'),
('MRS Advanced Certificate in Market and Social Research Practice','Reporting','exam','A client wants the report to omit a finding that is unfavourable to their new product. The researcher should','Omit it, since the client commissioned the work','Omit it but mention it verbally','Decline to present a partial account that would mislead, and ensure the findings are reported completely and fairly','Reframe the finding as positive','C','Professional codes require findings to be reported fairly and not in a way that misleads, regardless of who paid. Selective omission and reframing both produce a misleading account.'),
('MRS Advanced Certificate in Market and Social Research Practice','Reporting','exam','Which element is essential in the technical appendix of a published research report?','The researcher''s CV','The client''s marketing plan','Method, sample frame, sample size, fieldwork dates, response rate, weighting and the question wording used','The invoice total','C','These are the details a reader needs to judge whether the findings support the claims made from them. Without them the numbers cannot be evaluated at all.'),
('MRS Advanced Certificate in Market and Social Research Practice','Reporting','exam','A press release states "8 out of 10 buyers prefer our marketplace". The minimum required disclosure alongside it is','The company''s founding date','The software used','The name of the analyst','Who was surveyed, how many, when, how they were selected and the exact question asked','D','Published claims must carry enough method detail for the audience to judge them, which is the core transparency obligation. Without the base and the question, the claim is unverifiable.'),
('MRS Advanced Certificate in Market and Social Research Practice','Reporting','hard','Findings must be presented to an executive who will make a pricing decision this week. The strongest report structure is','Chronological description of the fieldwork, then the data, then a conclusion','Every crosstab, with the reader left to interpret','The decision-relevant conclusion first, with the supporting evidence, the confidence in it and its stated limitations, and full method in an appendix','A single headline number with no caveats','C','A decision-maker needs the answer, the strength of the evidence and its limits, in that order, with method available but not blocking. Chronology and undigested tables force the reader to do the analysis, and a bare number hides the uncertainty they need.'),
('MRS Advanced Certificate in Market and Social Research Practice','Research design','exam','Which is a genuine hypothesis rather than a research objective?','To understand supplier attitudes','To improve satisfaction','To explore the market','Suppliers who receive an RFQ within 24 hours of registering are more likely to quote than those who do not','D','A hypothesis states a testable, falsifiable relationship between defined variables. The others describe intent without anything that could be shown false.'),
('MRS Advanced Certificate in Market and Social Research Practice','Data collection','exam','A questionnaire takes 28 minutes online. The most likely data quality consequence is','Better considered answers throughout','Higher response rates','No effect','Increased break-off and straight-lining in the later sections, degrading the quality of those items','D','Respondent fatigue on long online instruments produces drop-out and low-effort responding concentrated in later sections. Item order and length must therefore be designed around the attention available.'),
('MRS Advanced Certificate in Market and Social Research Practice','Sampling','hard','A B2B study needs 200 interviews with procurement decision makers in a population of about 3,000 firms. The best frame strategy is','Convenience interviews at a trade show','Interviewing whoever answers the switchboard','Social media advertising','A defined list-based frame of the 3,000 firms with randomised selection and documented screening for the decision-maker role','D','A defined list frame with random selection and a screening rule gives known coverage of the population and an identifiable respondent role. Trade shows, advertising and switchboard contacts all produce uncontrolled self-selection.'),
('MRS Advanced Certificate in Market and Social Research Practice','Analysis and interpretation','hard','Two waves show satisfaction of 71 and 74 percent, each with n = 500. Roughly, the 95 percent interval on each is about plus or minus 4 points. The defensible statement is','Satisfaction improved by 3 points','The second wave is unreliable','Satisfaction improved significantly','The two waves are not distinguishable at this sample size; no change is demonstrated','D','Intervals of about four points around each estimate overlap substantially, so the data do not support a claim of change. Stating that plainly is more useful than reporting a movement within noise.'),
('MRS Advanced Certificate in Market and Social Research Practice','Ethics and the MRS Code of Conduct','exam','An incentive of AED 200 is offered for a 10-minute survey among low-income participants. The ethical concern is','Incentives are never permitted','Incentives must always be non-monetary','The amount is too small','The incentive may be coercive relative to the burden and the participants'' circumstances, compromising voluntary participation','D','An incentive large enough to override a participant''s own judgement about taking part undermines voluntariness. Incentives are permitted, but must be proportionate to the burden and the population.'),
('MRS Advanced Certificate in Market and Social Research Practice','Reporting','exam','A chart in a client deck shows a bar axis starting at 60 percent, exaggerating a small gap. The researcher should','Leave it, since the numbers are labelled','Remove the chart entirely','Add a footnote only','Correct the axis or change the encoding so the visual proportion matches the data, because the visual is part of the finding','D','A chart communicates a magnitude visually and a misleading encoding misleads even when the numbers are printed. Fixing the encoding is part of reporting fairly.'),
('MRS Advanced Certificate in Market and Social Research Practice','Research design','exam','Longitudinal panel research differs from repeated cross-sections in that','A panel re-interviews the same individuals, allowing individual-level change to be measured, but risks panel conditioning and attrition','A panel is always cheaper','Repeated cross-sections measure individual change','There is no practical difference','A','Following the same people is what makes individual-level change observable, and it brings conditioning and attrition as the price. Independent cross-sections measure net change in the population only.'),
('MRS Advanced Certificate in Market and Social Research Practice','Data collection','exam','Passive behavioural data from the platform is proposed instead of a survey about how buyers search. The main trade-off is','Behavioural data shows what people did without recall error, but not why they did it','Behavioural data is always less accurate','Surveys never suffer recall error','Behavioural data requires no ethical consideration','A','Observed behaviour removes recall and social desirability error but is silent on motivation and meaning. Combining it with self-report is how the why is recovered.'),
('MRS Advanced Certificate in Market and Social Research Practice','Analysis and interpretation','exam','After collecting data, the researcher tests 20 subgroup differences and reports the two that reached p < 0.05. This practice is','Sound, because significance was reached','Acceptable if the subgroups were interesting','Data dredging: at 20 tests, roughly one significant result is expected by chance, so the findings must be pre-registered or corrected and labelled exploratory','Only a problem for qualitative research','C','With many tests, the chance of at least one false positive is high, so undeclared selective reporting overstates the evidence. Pre-registration, correction, or explicit exploratory labelling restores honesty.'),
('MRS Advanced Certificate in Market and Social Research Practice','Research design','hard','A client demands a study design that will "prove" their new pricing is preferred. The professional response is','Design the study as requested, since the client sets the brief','Use a smaller sample so the result is less certain','Run the study and report only supportive findings','Decline the framing and design a study capable of returning either result, explaining that a design that can only confirm cannot inform a decision','D','A design incapable of disconfirming the hypothesis produces no information and breaches the obligation to conduct research objectively. Explaining why a falsifiable design serves the client''s decision better is part of the professional role.')
) as v(certification, syllabus_area, difficulty, question, option_a, option_b, option_c, option_d, correct_option, rationale)
where not exists (select 1 from public.certification_exam_question where certification = 'MRS Advanced Certificate in Market and Social Research Practice');

-- ============================== proof: every bank in this batch has >= 40 questions on production ==============================
do $$
declare
  r record;
  missing text := '';
begin
  for r in
    select c.certification, coalesce(qq.n, 0) as n
    from (values
      ('CAP (Certified Analytics Professional)'),
      ('CDMP (Certified Data Management Professional)'),
      ('Google Professional Data Engineer'),
      ('Microsoft PL-300 Power BI Data Analyst'),
      ('CKM (Certified Knowledge Manager)'),
      ('MRS Advanced Certificate in Market and Social Research Practice')
    ) as c(certification)
    left join (
      select certification, count(*) as n
      from public.certification_exam_question
      group by certification
    ) qq on qq.certification = c.certification
  loop
    if r.n < 40 then
      missing := missing || format('%s has %s questions; ', r.certification, r.n);
    end if;
  end loop;
  if missing <> '' then
    raise exception 'certifications_data_analytics: bank(s) below 40 questions: %', missing;
  end if;
end $$;
